        case "lose":
          [392, 330, 262, 196].forEach((f, i) => this.tone(f, { type: "triangle", dur: 0.38, vol: 0.11, delay: i * 0.18, slide: -18 }));
          break;
        default:
          break;
      }
    }
  };

  BTD.Sound = Sound;
})();

