    ctx.fillStyle = "rgba(32, 25, 17, 0.4)";
    roundRect(ctx, -12, -13.2, 24, 3.6, 1.8);
    ctx.fill();
    ctx.fillStyle = p.accent;
    roundRect(ctx, -2.5, -13.5, 5, 4.2, 1.2);
    ctx.fill();

    // Neck
    ctx.fillStyle = p.fur;
    roundRect(ctx, -4.5, -37, 9, 8, 3.5);
    ctx.fill();

    // Ears (behind head)
    ctx.fillStyle = p.furDark;
    ellipse(ctx, -13.4, -46, 6, 6.4);
    ellipse(ctx, 13.4, -46, 6, 6.4);
    ctx.fillStyle = TAN;
