      ctx.fillStyle = "#e05b3e";
      ctx.beginPath();
      ctx.moveTo(-5, 0);
      ctx.lineTo(-9, -3.8);
      ctx.lineTo(-2.5, -1.4);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-5, 0);
      ctx.lineTo(-9, 3.8);
      ctx.lineTo(-2.5, 1.4);
      ctx.closePath();
      ctx.fill();
    } else if (type === "boomerang") {
      ctx.rotate(time * 0.8);
      ctx.strokeStyle = "#b66a26";
      ctx.lineWidth = 4.4;
      ctx.beginPath();
      ctx.moveTo(-8, -3);
      ctx.quadraticCurveTo(4, -9, 10, 1);
      ctx.quadraticCurveTo(4, -2, -2, 2);
      ctx.stroke();
      ctx.strokeStyle = "#f2bd52";
      ctx.lineWidth = 2.1;
      ctx.beginPath();
      ctx.moveTo(-7, -3.5);
      ctx.quadraticCurveTo(3, -8, 8.5, 0);
      ctx.stroke();
    } else if (type === "bomb") {
