      ctx.arc(4, 1, 6.2, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = "#5c5963";
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = "rgba(255,255,255,.4)";
