      for (let i = 0; i < 3; i++) ellipse(ctx, -9 + i * 7, -8.5 - i, 0.6, 0.5);
    }
    ctx.restore();
  }

  function drawFlower(ctx, x, y, s, rng) {
    const colors = ["#ffe16c", "#ff8a8a", "#d7a4ff", "#fff3e5", "#ffb04f"];
    const color = colors[(rng() * colors.length) | 0];
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.strokeStyle = "#3c7b33";
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(-1.5, -5, 0, -9);
    ctx.stroke();
    ctx.fillStyle = "#55a342";
    ellipse(ctx, -2.5, -3.5, 2.3, 1.1);
    ctx.fillStyle = color;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU + rng() * 0.4;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 3, -9 + Math.sin(a) * 3, 2.3, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = "#f5b62e";
    ellipse(ctx, 0, -9, 1.5, 1.5);
    ctx.restore();
  }

  function drawRock(ctx, x, y, s, rng) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.fillStyle = "rgba(25, 42, 19, .2)";
    ellipse(ctx, 2, 1, 11, 3.5);
    const g = ctx.createLinearGradient(0, -9, 0, 1);
    g.addColorStop(0, "#a6a795");
    g.addColorStop(0.55, "#7d806f");
    g.addColorStop(1, "#575c4d");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-9, 0);
    ctx.lineTo(-7, -6);
    ctx.lineTo(-2, -9 + rng() * 1.5);
    ctx.lineTo(5, -8);
    ctx.lineTo(9, -2);
    ctx.lineTo(6, 0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(57, 62, 50, .45)";
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.fillStyle = "rgba(255, 251, 226, .18)";
    ctx.beginPath();
    ctx.moveTo(-6, -6);
    ctx.lineTo(-2, -8);
    ctx.lineTo(3, -6.4);
    ctx.lineTo(-1, -5);
    ctx.closePath();
    ctx.fill();
    if (rng() < 0.55) {
      ctx.fillStyle = "#5a8c3d";
      ellipse(ctx, 6, -3, 3.3, 1.7);
      ellipse(ctx, 8, -4, 2, 1.2);
    }
    ctx.restore();
  }

  function drawGrassTuft(ctx, x, y, s, rng, flip = false) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(flip ? -s : s, s);
    ctx.strokeStyle = rng() < 0.45 ? "rgba(45, 107, 39, .8)" : "rgba(110, 161, 61, .75)";
    ctx.lineWidth = 1.3;
    ctx.lineCap = "round";
    for (let i = 0; i < 5; i++) {
      const ox = (i - 2) * 3.1;
      ctx.beginPath();
      ctx.moveTo(ox, 0);
      ctx.quadraticCurveTo(ox + (rng() - 0.5) * 5, -5, ox + (i - 2) * 2.6, -9 - rng() * 5);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawMushroom(ctx, x, y, s, rng) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.strokeStyle = "#e7dbbd";
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -5);
    ctx.stroke();
    ctx.fillStyle = rng() < 0.5 ? "#d9523d" : "#e1a24a";
    ctx.beginPath();
    ctx.arc(0, -5, 5.5, Math.PI, TAU);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "rgba(255, 246, 220, .75)";
    ellipse(ctx, -2, -8, 1.3, 0.9);
    ellipse(ctx, 2, -7, 0.8, 0.6);
    ctx.restore();
  }

  function drawPond(ctx, x, y, rx, ry, rng) {
    ctx.save();
    const g = ctx.createRadialGradient(x - rx * 0.2, y - ry * 0.3, 2, x, y, rx);
    g.addColorStop(0, "#8ed9c8");
    g.addColorStop(0.45, "#54b7b5");
    g.addColorStop(0.85, "#267d86");
    g.addColorStop(1, "#1c5d6a");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, -0.08, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = "rgba(35, 84, 52, .55)";
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.strokeStyle = "rgba(191, 255, 244, .3)";
    ctx.lineWidth = 1.3;
    for (let i = 0; i < 5; i++) {
      const yy = y - ry * 0.42 + i * ry * 0.23;
      const xx = x + (rng() - 0.5) * rx * 0.45;
      ctx.beginPath();
      ctx.ellipse(xx, yy, rx * (0.16 + rng() * 0.15), 1.2 + rng(), 0, 0, TAU);
      ctx.stroke();
    }
    // Lily pads
    for (let i = 0; i < 3; i++) {
      const px = x + (rng() - 0.5) * rx * 1.2;
      const py = y + (rng() - 0.5) * ry * 1.1;
      ctx.fillStyle = "#4a9e3f";
      ctx.beginPath();
      ctx.ellipse(px, py, 6 + rng() * 3, 3 + rng() * 1.5, rng() * 0.5, 0.3, TAU - 0.3);
      ctx.fill();
      if (rng() < 0.45) {
        ctx.fillStyle = "#ffd3e4";
        ellipse(ctx, px + 2, py - 1, 2.1, 1.6);
      }
    }
    ctx.restore();
  }

  function drawSign(ctx, x, y, s, text = "START") {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.fillStyle = "rgba(28, 47, 20, .22)";
    ellipse(ctx, 5, 2, 16, 4);
    ctx.fillStyle = "#68472a";
    roundRect(ctx, -2, -23, 5, 24, 2);
    ctx.fill();
    ctx.fillStyle = "#835b34";
    roundRect(ctx, -19, -34, 41, 17, 3);
    ctx.fill();
    ctx.strokeStyle = "#4f321c";
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.fillStyle = "rgba(255, 238, 191, .16)";
    roundRect(ctx, -16, -32, 35, 5, 2);
    ctx.fill();
    ctx.fillStyle = "#f8e5bb";
    ctx.font = "800 8px 'Trebuchet MS', sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, 2, -25.5);
    ctx.fillStyle = "#f4c858";
    ctx.beginPath();
    ctx.moveTo(17, -25.5);
    ctx.lineTo(12, -29);
    ctx.lineTo(12, -22);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawGate(ctx, x, y, s, time = 0) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.fillStyle = "rgba(23, 40, 16, .24)";
    ellipse(ctx, 8, 4, 27, 7);
    ctx.fillStyle = "#67462a";
    roundRect(ctx, -24, -36, 7, 37, 2);
    ctx.fill();
    roundRect(ctx, 17, -36, 7, 37, 2);
    ctx.fill();
    ctx.fillStyle = "#7d5732";
    roundRect(ctx, -28, -41, 56, 8, 3);
    ctx.fill();
    ctx.strokeStyle = "#4d311b";
    ctx.lineWidth = 1.2;
    ctx.stroke();
    // Hanging leaves and little charm
    ctx.strokeStyle = "#3d7d34";
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(-21, -34);
    ctx.quadraticCurveTo(-17, -25, -22, -18);
    ctx.moveTo(20, -34);
    ctx.quadraticCurveTo(24, -24, 20, -17);
    ctx.stroke();
    ctx.fillStyle = "#4e9a3e";
    ellipse(ctx, -22, -18, 4, 2);
    ellipse(ctx, 20, -17, 4, 2);
    ctx.fillStyle = "#f4c858";
    ctx.beginPath();
    ctx.moveTo(0, -47);
    ctx.lineTo(7, -37);
    ctx.lineTo(0, -27);
    ctx.lineTo(-7, -37);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#8d5a1b";
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = "#fff2bf";
    star(ctx, 0, -38, 3.1);
    ctx.restore();
  }

  function drawTorch(ctx, x, y, s, time = 0) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.fillStyle = "rgba(30, 44, 17, .24)";
    ellipse(ctx, 2, 2, 7, 2.5);
    ctx.fillStyle = "#654328";
    roundRect(ctx, -2, -25, 4.5, 26, 2);
    ctx.fill();
    ctx.fillStyle = "#3f6b30";
    roundRect(ctx, -4.8, -24, 10, 4, 2);
    ctx.fill();
    ctx.fillStyle = "#86592c";
    roundRect(ctx, -6, -30, 12, 5, 2.5);
    ctx.fill();
    const flick = Math.sin(time * 12 + x) * 1.4;
    const fg = ctx.createRadialGradient(0, -35, 1, 0, -35, 13);
    fg.addColorStop(0, "rgba(255, 249, 176, .95)");
    fg.addColorStop(0.35, "rgba(255, 185, 52, .9)");
    fg.addColorStop(1, "rgba(255, 82, 20, 0)");
    ctx.fillStyle = fg;
    ellipse(ctx, flick * 0.3, -36 - Math.abs(flick) * 0.3, 8 + flick, 13);
    ctx.fillStyle = "rgba(255, 250, 196, .9)";
    ellipse(ctx, flick * 0.2, -35, 2.6, 5.5);
    ctx.restore();
  }

  function drawButterfly(ctx, x, y, s, time, phase, color = "#ffd55c") {
    const flap = Math.abs(Math.sin(time * 9 + phase));
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(Math.sin(time * 2.4 + phase) * 0.2);
    ctx.scale(s, s);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(-4, 0, 4.5, 3 + flap * 2.3, -0.4, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(4, 0, 4.5, 3 + flap * 2.3, 0.4, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,.35)";
    ellipse(ctx, -4.5, -1, 1.6, 1.2);
    ellipse(ctx, 4.5, -1, 1.6, 1.2);
    ctx.fillStyle = "#4b3c2b";
    ellipse(ctx, 0, 0, 0.9, 3.2);
    ctx.restore();
  }

  BTD.WorldArt = {
    drawTree,
    drawBush,
    drawFlower,
    drawRock,
    drawGrassTuft,
    drawMushroom,
    drawPond,
    drawSign,
    drawGate,
    drawTorch,
    drawButterfly
  };
})();

/* =========================================================
   BLOONS TD 5 — SUNSET GROVE
   Smooth track geometry.
   ========================================================= */
(() => {
  "use strict";
  const BTD = (window.BTD = window.BTD || {});
  const { TAU, clamp } = BTD;

  const DESKTOP_POINTS = [
    [-0.06, 0.29], [0.08, 0.29], [0.16, 0.43], [0.255, 0.55],
    [0.35, 0.575], [0.445, 0.475], [0.445, 0.325], [0.535, 0.195],
    [0.655, 0.19], [0.735, 0.3], [0.715, 0.44], [0.79, 0.56],
    [0.9, 0.6], [0.972, 0.5], [1.06, 0.455]
  ];

  const MOBILE_POINTS = [
    [-0.08, 0.065], [0.17, 0.075], [0.5, 0.105], [0.74, 0.175],
    [0.82, 0.275], [0.69, 0.36], [0.41, 0.37], [0.2, 0.425],
    [0.17, 0.515], [0.27, 0.6], [0.53, 0.635], [0.78, 0.69],
    [0.84, 0.79], [0.72, 0.875], [0.46, 0.92], [0.24, 0.97],
    [0.13, 1.06]
  ];

  class Track {
    constructor(w, h) {
      this.w = w;
      this.h = h;
      const mobile = w / h < 1.18;
      const controls = (mobile ? MOBILE_POINTS : DESKTOP_POINTS).map(([x, y]) => ({ x: x * w, y: y * h }));
      this.controls = controls;
      this.points = this._smooth(controls);
      this.cum = [0];
      this.length = 0;
      for (let i = 1; i < this.points.length; i++) {
        this.length += Math.hypot(this.points[i].x - this.points[i - 1].x, this.points[i].y - this.points[i - 1].y);
        this.cum.push(this.length);
      }
      this.start = this.pointAt(0.012);
      this.end = this.pointAt(0.988);
    }

    _smooth(controls) {
      const pts = [];
      const cp = [controls[0], ...controls, controls[controls.length - 1]];
      for (let i = 1; i < cp.length - 2; i++) {
        const p0 = cp[i - 1];
        const p1 = cp[i];
        const p2 = cp[i + 1];
        const p3 = cp[i + 2];
        const segLen = Math.hypot(p2.x - p1.x, p2.y - p1.y);
        const steps = clamp(Math.ceil(segLen / 7), 6, 34);
        for (let s = 0; s < steps; s++) {
          const t = s / steps;
          const t2 = t * t;
          const t3 = t2 * t;
          const x = 0.5 * (2 * p1.x + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3);
          const y = 0.5 * (2 * p1.y + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3);
          pts.push({ x, y });
        }
      }
      pts.push({ ...controls[controls.length - 1] });
      return pts;
    }

    pointAt(t) {
      const target = clamp(t, 0, 1) * this.length;
      let lo = 0;
      let hi = this.cum.length - 1;
      while (lo < hi - 1) {
        const mid = (lo + hi) >> 1;
        if (this.cum[mid] <= target) lo = mid;
        else hi = mid;
      }
      const a = this.points[lo];
      const b = this.points[Math.min(lo + 1, this.points.length - 1)];
      const seg = Math.max(0.0001, this.cum[lo + 1] - this.cum[lo]);
      const f = clamp((target - this.cum[lo]) / seg, 0, 1);
      const x = a.x + (b.x - a.x) * f;
      const y = a.y + (b.y - a.y) * f;
      const angle = Math.atan2(b.y - a.y, b.x - a.x);
      return { x, y, angle, nx: -Math.sin(angle), ny: Math.cos(angle) };
    }

    nearest(x, y) {
      let best = Infinity;
      let index = 0;
      for (let i = 0; i < this.points.length; i += 2) {
        const p = this.points[i];
        const d = (p.x - x) ** 2 + (p.y - y) ** 2;
        if (d < best) {
          best = d;
          index = i;
        }
      }
      return { distance: Math.sqrt(best), x: this.points[index].x, y: this.points[index].y, index };
    }

    pointAlongDistance(d) {
      return this.pointAt(d / this.length);
    }

    draw(ctx, width, scale) {
      const path = new Path2D();
      path.moveTo(this.points[0].x, this.points[0].y);
      for (let i = 1; i < this.points.length; i++) path.lineTo(this.points[i].x, this.points[i].y);

      ctx.save();
      ctx.lineJoin = "round";
      ctx.lineCap = "round";

      // Soft moss shadow / border
      ctx.strokeStyle = "rgba(36, 69, 29, .4)";
      ctx.lineWidth = width + 12 * scale;
      ctx.stroke(path);

      ctx.strokeStyle = "#70502c";
      ctx.lineWidth = width + 3 * scale;
      ctx.stroke(path);

      ctx.strokeStyle = "#b3834b";
      ctx.lineWidth = width - 3 * scale;
      ctx.stroke(path);

      const dirt = ctx.createLinearGradient(0, 0, this.w, this.h);
      dirt.addColorStop(0, "#d9b079");
      dirt.addColorStop(0.5, "#c99d63");
      dirt.addColorStop(1, "#e1ba82");
      ctx.strokeStyle = dirt;
      ctx.lineWidth = width - 10 * scale;
      ctx.stroke(path);

      // Sunlit inner ribbon
      ctx.strokeStyle = "rgba(255, 231, 170, .14)";
      ctx.lineWidth = width * 0.32;
      ctx.stroke(path);
      ctx.restore();

      // Dirt speckles and little stones
      const rng = BTD.makeRng(1977 + Math.round(width));
      for (let i = 0; i < 130; i++) {
        const p = this.pointAt(rng());
        const side = (rng() - 0.5) * width * 0.72;
        const x = p.x + p.nx * side;
        const y = p.y + p.ny * side;
        if (rng() < 0.7) {
          ctx.fillStyle = `rgba(107, 72, 39, ${0.12 + rng() * 0.15})`;
          ctx.beginPath();
          ctx.ellipse(x, y, (1 + rng() * 2.2) * scale, (0.7 + rng() * 1.4) * scale, rng() * 3, 0, TAU);
          ctx.fill();
        } else {
          ctx.fillStyle = `rgba(245, 217, 166, ${0.2 + rng() * 0.22})`;
          ctx.beginPath();
          ctx.ellipse(x, y, (1.2 + rng() * 2.1) * scale, (0.8 + rng() * 1.2) * scale, rng() * 3, 0, TAU);
          ctx.fill();
        }
      }

      // Footprints / tiny dashed trail dots
      ctx.save();
      ctx.setLineDash([2 * scale, 13 * scale]);
      ctx.lineDashOffset = 4;
      ctx.strokeStyle = "rgba(112, 77, 42, .2)";
      ctx.lineWidth = 1.2 * scale;
      ctx.stroke(path);
      ctx.restore();
    }
  }

  BTD.Track = Track;
})();

/* =========================================================
   BLOONS TD 5 — SUNSET GROVE
   Towers, bloons, and projectiles.
   ========================================================= */
(() => {
  "use strict";
  const BTD = (window.BTD = window.BTD || {});
  const { TOWERS, BLOONS, TAU, clamp, dist } = BTD;

  let nextId = 1;
  const TARGET_MODES = [
    { key: "first", label: "First", hint: "Targets the bloon furthest along the track." },
    { key: "last", label: "Last", hint: "Targets the bloon furthest behind." },
    { key: "close", label: "Close", hint: "Targets the bloon nearest this tower." },
    { key: "strong", label: "Strong", hint: "Targets the toughest bloon in range." }
  ];

  // -------------------------------------------------------
  // Tower
  // -------------------------------------------------------
  class Tower {
    constructor(game, type, nx, ny, opts = {}) {
      this.game = game;
      this.id = nextId++;
      this.type = type;
      this.def = TOWERS[type];
      this.nx = nx;
      this.ny = ny;
      this.level = 0;
      this.mode = 0;
      this.cooldown = 0.2 + Math.random() * 0.25;
      this.aim = -Math.PI / 2;
      this.seed = Math.random() * TAU;
      this.recoil = 0;
      this.flash = 0;
      this.age = 0;
      this.placeAnim = 0;
      this.isScout = !!opts.scout;
      this.spent = opts.scout ? 0 : this.def.cost;
      this.specials = new Set();
      this.stats = this.computeStats();
    }

    get x() { return this.nx * this.game.w; }
    get y() { return this.ny * this.game.h; }
    get scale() { return this.game.scale; }
    get range() { return this.stats.range * this.scale; }
    get sellValue() { return this.isScout ? Math.floor(this.spent * 0.7) : Math.floor(this.spent * 0.7); }
    get upgrade() { return this.def.upgrades[this.level] || null; }
    get maxed() { return this.level >= this.def.upgrades.length; }

    computeStats() {
      const s = { ...this.def.base };
      const specials = new Set();
      for (let i = 0; i < this.level; i++) {
        const up = this.def.upgrades[i];
        if (!up) continue;
        if (up.special) specials.add(up.special);
        for (const [key, value] of Object.entries(up.mods || {})) {
          if (key.endsWith("Mul")) {
            const baseKey = key.slice(0, -3);
            s[baseKey] = (s[baseKey] || 0) * value;
          } else {
            s[key] = (s[key] || 0) + value;
          }
        }
      }
      this.specials = specials;
      return s;
    }

    recompute() {
      this.stats = this.computeStats();
    }

    upgradeTower() {
      if (this.maxed) return false;
      const up = this.upgrade;
      if (this.game.money < up.cost) return false;
      this.game.money -= up.cost;
      this.spent += up.cost;
      this.level++;
      this.recompute();
      this.placeAnim = 0.5;
      this.game.sound("upgrade");
      this.game.addRing(this.x, this.y, 10 * this.scale, 56 * this.scale, "#ffd45e", 0.55, true);
      this.game.addParticles(this.x, this.y - 25 * this.scale, "#ffd45e", 14, 80 * this.scale, 0.7, "star");
      this.game.addFloater(this.x, this.y - 50 * this.scale, "UPGRADED!", "#ffe27d", 1.1, 13);
      this.game.dirty = true;
      return true;
    }

    cycleMode() {
      this.mode = (this.mode + 1) % TARGET_MODES.length;
      this.game.sound("click");
      this.game.dirty = true;
      return TARGET_MODES[this.mode];
    }

    modeInfo() { return TARGET_MODES[this.mode]; }

    sell() {
      const value = this.sellValue;
      this.game.money += value;
      this.game.towers = this.game.towers.filter((t) => t !== this);
      this.game.addParticles(this.x, this.y - 15 * this.scale, "#ffe08a", 14, 70 * this.scale, 0.7, "star");
      this.game.addFloater(this.x, this.y - 38 * this.scale, `+$${value}`, "#ffe27d", 0.9, 12);
      this.game.sound("sell");
      this.game.dirty = true;
      return value;
    }

    update(dt) {
      this.age += dt;
      this.placeAnim = Math.max(0, this.placeAnim - dt);
      this.recoil = Math.max(0, this.recoil - dt * 6);
      this.flash = Math.max(0, this.flash - dt);
      this.cooldown -= dt;

      if (this.specials.has("ringOfFire")) {
        const target = this.game.findTarget(this);
        if (target) {
          this.aim = Math.atan2(target.position().y - this.y, target.position().x - this.x);
          if (this.cooldown <= 0) {
            this.game.ringOfFire(this);
            this.cooldown = 0.34;
          }
        } else {
          this.cooldown = Math.max(this.cooldown, 0.12);
        }
        return;
      }

      const target = this.game.findTarget(this);
      if (!target) return;
      const p = target.position();
      this.aim = Math.atan2(p.y - (this.y - 28 * this.scale), p.x - this.x);
      if (this.cooldown <= 0) {
        this.cooldown = this.stats.cd;
        this.recoil = 1;
        this.flash = 0.08;
        this.game.fireTower(this, target);
      }
    }
  }

  // -------------------------------------------------------
  // Bloon
  // -------------------------------------------------------
  class Bloon {
    constructor(game, type, t = 0, offset = 0, opts = {}) {
      this.game = game;
      this.id = nextId++;
      this.type = type;
      this.def = BLOONS[type];
      this.t = t;
      this.offset = offset;
      this.hp = this.def.hp;
      this.dead = false;
      this.leaked = false;
      this.flash = 0;
      this.phase = Math.random() * TAU;
      this.slowUntil = 0;
      this.slowFactor = 1;
      this.freezeUntil = 0;
      this.age = 0;
      this.spawnPop = opts.silent ? 0.22 : 0;
    }

    get radius() { return this.def.radius * this.game.scale; }
    get big() { return !!this.def.big; }

    position() {
      const p = this.game.track.pointAt(this.t);
      return {
        x: p.x + p.nx * this.offset,
        y: p.y + p.ny * this.offset,
        angle: p.angle,
        nx: p.nx,
        ny: p.ny
      };
    }

    get speed() {
      if (this.freezeUntil > this.game.time) return 0;
      if (this.slowUntil > this.game.time) return this.slowFactor;
      return 1;
    }

    update(dt) {
      this.age += dt;
      this.flash = Math.max(0, this.flash - dt);
      this.spawnPop = Math.max(0, this.spawnPop - dt);
      const slow = this.speed;
      if (slow > 0) {
        this.t += this.def.speed * BTD.SPEED_SCALE * slow * dt;
      }
      if (this.t >= 1) {
        this.t = 1;
        this.leak();
      }
    }

    applyGlue(factor, duration) {
      this.slowFactor = Math.min(this.slowFactor === 1 ? factor : this.slowFactor, factor);
      this.slowUntil = Math.max(this.slowUntil, this.game.time + duration);
    }

    freeze(duration) {
      if (this.def.freezeResist) return false;
      this.freezeUntil = Math.max(this.freezeUntil, this.game.time + duration);
      return true;
    }

    leak() {
      if (this.dead) return;
      this.dead = true;
      this.leaked = true;
      const p = this.position();
      this.game.onLeak(this, p);
    }

    damage(amount, source = {}) {
      if (this.dead || amount <= 0) return;
      if (source.kind === "explosion" && this.def.immuneExplosion) {
        this.flash = 0.06;
        if (Math.random() < 0.25) this.game.addFloater(this.position().x, this.position().y - 6, "resist", "#d7d2c0", 0.5, 8);
        return;
      }
      this.hp -= amount;
      this.flash = 0.13;
      if (this.hp > 0) {
        if (amount >= 2 || this.big) this.game.addParticles(this.position().x, this.position().y, this.def.light, 3, 45, 0.35, "spark");
        return;
      }

      const overflow = -this.hp;
      this.dead = true;
      this.game.onBloonPopped(this);
      const p = this.position();
      const children = this.def.children || [];
      for (let i = 0; i < children.length; i++) {
        const child = this.game.spawnBloon(children[i], this.t, this.offset + BTD.rand(-6, 6), { silent: true });
        if (child && overflow > 0 && i === 0) {
          child.damage(overflow, source);
        }
      }
      if (this.big && children.length) {
        this.game.addRing(p.x, p.y, 8, this.radius * 2.5, this.def.light, 0.5, true);
        this.game.shake = Math.max(this.game.shake, 6);
      }
    }
  }

  // -------------------------------------------------------
  // Projectile
  // -------------------------------------------------------
  class Projectile {
    constructor(game, opts) {
      this.game = game;
      this.id = nextId++;
      Object.assign(this, {
        kind: "dart",
        x: 0,
        y: 0,
        vx: 0,
        vy: 0,
        speed: 500,
        damage: 1,
        pierce: 1,
        life: 1.4,
        maxLife: 1.4,
        angle: 0,
        spin: 0,
        returning: false,
        returnAfter: 0.42,
        age: 0,
        dead: false,
        hitSet: new Set(),
        trail: [],
        splash: 0,
        source: null,
        color: "#fff",
        size: 1,
        isBig: false
      }, opts);
      this.maxLife = this.life;
      if (this.speed > 0 && this.kind !== "bomb") {
        this.vx = Math.cos(this.angle) * this.speed;
        this.vy = Math.sin(this.angle) * this.speed;
      }
    }

    update(dt) {
      this.age += dt;
      this.life -= dt;
      if (this.life <= 0) {
        this.dead = true;
        if (this.kind === "bomb") this.explode();
        return;
      }

      if (this.kind === "bomb") {
        const t = clamp(this.age / this.duration, 0, 1);
        this.x = this.sx + (this.tx - this.sx) * t;
        this.y = this.sy + (this.ty - this.sy) * t;
        this.z = Math.sin(t * Math.PI) * this.arc;
        if (t >= 1) this.explode();
        return;
      }

      if (this.kind === "boomerang") {
        if (this.age > this.returnAfter) {
          const tx = this.source ? this.source.x : this.sx;
          const ty = this.source ? this.source.y : this.sy;
          const a = Math.atan2(ty - this.y, tx - this.x);
          this.vx += Math.cos(a) * this.speed * 3.2 * dt;
          this.vy += Math.sin(a) * this.speed * 3.2 * dt;
          const sp = Math.hypot(this.vx, this.vy);
          const cap = this.speed * 1.25;
          if (sp > cap) {
            this.vx = (this.vx / sp) * cap;
            this.vy = (this.vy / sp) * cap;
          }
          if (this.age > this.returnAfter && dist(this.x, this.y, tx, ty) < 22 * this.game.scale) this.dead = true;
        }
        this.spin += dt * 15;
      }

      this.x += this.vx * dt;
      this.y += this.vy * dt;
      this.trail.push({ x: this.x, y: this.y, life: 0.14 });
      if (this.trail.length > 9) this.trail.shift();
      for (const t of this.trail) t.life -= dt;

      if (this.x < -100 * this.game.scale || this.x > this.game.w + 100 * this.game.scale || this.y < -100 * this.game.scale || this.y > this.game.h + 100 * this.game.scale) {
        this.dead = true;
      }
    }

    explode() {
      if (this.dead) return;
      this.dead = true;
      this.game.explode(this.tx, this.ty, this.splash || 46, this.damage || 2, this.source, { cluster: this.cluster, color: this.color, sun: this.sun });
    }
  }

  BTD.Tower = Tower;
  BTD.Bloon = Bloon;
  BTD.Projectile = Projectile;
  BTD.TARGET_MODES = TARGET_MODES;
})();

/* =========================================================
   BLOONS TD 5 — SUNSET GROVE
   Core simulation: economy, waves, combat, particles.
   ========================================================= */
(() => {
  "use strict";
  const BTD = (window.BTD = window.BTD || {});
  const { TOWERS, BLOONS, ROUNDS, TAU, clamp, dist, rand, formatMoney, Sound } = BTD;
  const { Tower, Bloon, Projectile, TARGET_MODES } = BTD;

  class Game {
    constructor(canvas, stage) {
      this.canvas = canvas;
      this.stage = stage;
      this.ctx = canvas.getContext("2d");
      this.hooks = {};
      this.dpr = 1;
      this.w = 0;
      this.h = 0;
      this.scale = 1;
      this.pathWidth = 52;
      this.track = null;
      this.pond = null;
      this.scenery = { trees: [], bushes: [], flowers: [], rocks: [], grass: [], mushrooms: [], torches: [], sign: null, gate: null };
      this.background = null;
      this.butterflies = [];
      this.motes = [];
      this.leaves = [];

      this.money = 800;
      this.lives = 150;
      this.score = 0;
      this.pops = 0;
      this.round = 0;
      this.roundActive = false;
      this.roundClock = 0;
      this.spawnPlan = [];
      this.roundTotal = 0;
      this.roundSpawned = 0;
      this.autoTimer = 0;
      this.autoStart = false;
      this.endDelay = 0;
      this.gameOver = false;
      this.won = false;
      this.paused = false;
      this.speed = 1;
      this.time = 0;
      this.realTime = 0;
      this.shake = 0;
      this.hurtFlash = 0;
      this.dirty = true;

      this.towers = [];
      this.bloons = [];
      this.projectiles = [];
      this.particles = [];
      this.rings = [];
      this.floaters = [];
      this.tracers = [];

      this.selectedType = null;
      this.selectedTower = null;
      this.hoveredTower = null;
      this.pointer = { x: -999, y: -999, inside: false };
      this.ghostValid = false;
      this.ghostReason = "";
      this.tutorialDismissed = false;

      this.resize();
      this.placeStarter();
    }

    // -----------------------------------------------------
    // Layout
    // -----------------------------------------------------
    resize() {
      const rect = this.stage.getBoundingClientRect();
      const w = Math.max(240, rect.width);
      const h = Math.max(240, rect.height);
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      this.w = w;
      this.h = h;
      this.dpr = dpr;
      this.canvas.width = Math.round(w * dpr);
      this.canvas.height = Math.round(h * dpr);
      this.canvas.style.width = w + "px";
      this.canvas.style.height = h + "px";
      this.scale = clamp(Math.min(w / 1180, h / 670), 0.64, 1.12);
      this.pathWidth = 52 * this.scale;
      this.track = new BTD.Track(w, h);
      this.setupScenery();
      this.nudgeTowers();
      this.buildBackground();
      this.dirty = true;
    }

    setupScenery() {
      const { w, h, track, scale } = this;
      const rng = BTD.makeRng(4281 + Math.round(w * 3 + h * 7));
      this.pond = null;
      const pondCandidates = [
        [0.09, 0.84], [0.9, 0.84], [0.87, 0.13], [0.1, 0.13], [0.86, 0.46]
      ];
      for (const [nx, ny] of pondCandidates) {
        const x = nx * w;
        const y = ny * h;
        const rx = clamp(64 * scale, 39, 78);
        const ry = rx * 0.62;
        if (x - rx < 8 || x + rx > w - 8 || y - ry < 8 || y + ry > h - 8) continue;
        if (track.nearest(x, y).distance > rx + this.pathWidth * 0.85 + 12) {
          this.pond = { x, y, rx, ry };
          break;
        }
      }

      const isClear = (x, y, pad) => {
        if (x < -20 || x > w + 20 || y < -20 || y > h + 20) return false;
        if (track.nearest(x, y).distance < this.pathWidth * 0.5 + pad) return false;
        if (this.pond) {
          const dx = (x - this.pond.x) / (this.pond.rx + pad);
          const dy = (y - this.pond.y) / (this.pond.ry + pad);
          if (dx * dx + dy * dy < 1) return false;
        }
        return true;
      };

      const treeCount = Math.round(clamp(Math.min(w, h) / 35, 11, 22));
      this.scenery.trees = [];
      for (let i = 0; i < treeCount * 5 && this.scenery.trees.length < treeCount; i++) {
        let x, y;
        if (rng() < 0.72) {
          if (rng() < 0.5) x = rng() * w * 0.16;
          else x = w - rng() * w * 0.16;
          y = rng() * h;
        } else {
          x = rng() * w;
          y = rng() < 0.55 ? rng() * h * 0.12 : h - rng() * h * 0.12;
        }
        const palm = rng() < 0.18;
        const s = (palm ? 1.05 : 0.72) + rng() * 0.48;
        const pad = (palm ? 22 : 28) * s * scale;
        if (!isClear(x, y, pad)) continue;
        if (this.scenery.trees.some((t) => dist(t.x, t.y, x, y) < 42 * scale * Math.max(1, s))) continue;
        this.scenery.trees.push({ x, y, s, palm });
      }

      const bushCount = Math.round(clamp((w * h) / 26000, 12, 30));
      this.scenery.bushes = [];
      for (let i = 0; i < bushCount * 6 && this.scenery.bushes.length < bushCount; i++) {
        const x = rng() * w;
        const y = rng() * h;
        const s = 0.75 + rng() * 0.8;
        if (!isClear(x, y, 13 * s * scale)) continue;
        this.scenery.bushes.push({ x, y, s, berries: rng() < 0.3 });
      }

      const flowerCount = Math.round(clamp((w * h) / 11500, 25, 70));
      this.scenery.flowers = [];
      for (let i = 0; i < flowerCount * 4 && this.scenery.flowers.length < flowerCount; i++) {
        const x = rng() * w;
        const y = rng() * h;
        if (!isClear(x, y, 4)) continue;
        this.scenery.flowers.push({ x, y, s: 0.8 + rng() * 0.8 });
      }

      const rockCount = Math.round(clamp((w * h) / 62000, 6, 15));
      this.scenery.rocks = [];
      for (let i = 0; i < rockCount * 5 && this.scenery.rocks.length < rockCount; i++) {
        const x = rng() * w;
        const y = rng() * h;
        const s = 0.8 + rng() * 1.2;
        if (!isClear(x, y, 9 * s * scale)) continue;
        this.scenery.rocks.push({ x, y, s });
      }

      const grassCount = Math.round(clamp((w * h) / 9000, 30, 90));
      this.scenery.grass = [];
      for (let i = 0; i < grassCount * 3 && this.scenery.grass.length < grassCount; i++) {
        const x = rng() * w;
        const y = rng() * h;
        if (!isClear(x, y, 2)) continue;
        this.scenery.grass.push({ x, y, s: 0.7 + rng() * 0.7, flip: rng() < 0.5 });
      }

      this.scenery.mushrooms = [];
      for (let i = 0; i < 13; i++) {
        const x = rng() * w;
        const y = rng() * h;
        if (!isClear(x, y, 4)) continue;
        this.scenery.mushrooms.push({ x, y, s: 0.8 + rng() * 0.7 });
      }

      // Entrance sign and exit gate
      const start = track.pointAt(0.035);
      const end = track.pointAt(0.965);
      const insideSign = start.x < w * 0.5 ? 1 : -1;
      this.scenery.sign = {
        x: start.x + start.nx * (this.pathWidth * 0.5 + 30 * scale) * insideSign,
        y: start.y + start.ny * (this.pathWidth * 0.5 + 30 * scale) * insideSign
      };
      const insideGate = end.x < w * 0.5 ? 1 : -1;
      this.scenery.gate = {
        x: end.x + end.nx * (this.pathWidth * 0.5 + 35 * scale) * insideGate,
        y: end.y + end.ny * (this.pathWidth * 0.5 + 35 * scale) * insideGate
      };
      this.scenery.torches = [];
      for (const t of [0.1, 0.56, 0.89]) {
        const p = track.pointAt(t);
        const side = t === 0.1 ? -1 : 1;
        this.scenery.torches.push({
          x: p.x + p.nx * (this.pathWidth * 0.5 + 14 * scale) * side,
          y: p.y + p.ny * (this.pathWidth * 0.5 + 14 * scale) * side
        });
      }

      const count = Math.round(w / 170);
      this.butterflies = [];
      for (let i = 0; i < clamp(count, 3, 8); i++) {
        this.butterflies.push({
          x: rng() * w,
          y: h * (0.18 + rng() * 0.65),
          phase: rng() * TAU,
          speed: 0.3 + rng() * 0.5,
          range: 26 + rng() * 54,
          color: rng() < 0.45 ? "#ffd15e" : rng() < 0.6 ? "#f7a7c2" : "#bce8ff"
        });
      }

      this.motes = [];
      for (let i = 0; i < 24; i++) {
        this.motes.push({ x: rng() * w, y: rng() * h, phase: rng() * TAU, speed: 0.2 + rng() * 0.4, size: 0.7 + rng() * 1.3 });
      }

      this.leaves = [];
      for (let i = 0; i < 9; i++) {
        this.leaves.push({ x: rng() * w, y: rng() * h, phase: rng() * TAU, speed: 8 + rng() * 14, size: 2.4 + rng() * 2.4, drift: 10 + rng() * 18 });
      }
    }

    buildBackground() {
      const c = document.createElement("canvas");
      c.width = Math.round(this.w * this.dpr);
      c.height = Math.round(this.h * this.dpr);
      const ctx = c.getContext("2d");
      ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      this.renderBackground(ctx);
      this.background = c;
    }

    isSpotClear(x, y, ignore = null) {
      const margin = 18 * this.scale;
      if (x < margin || y < margin || x > this.w - margin || y > this.h - margin) return false;
      if (this.track.nearest(x, y).distance < this.pathWidth * 0.5 + 13 * this.scale) return false;
      if (this.pond) {
        const dx = (x - this.pond.x) / (this.pond.rx + 9 * this.scale);
        const dy = (y - this.pond.y) / (this.pond.ry + 9 * this.scale);
        if (dx * dx + dy * dy < 1) return false;
      }
      for (const t of this.towers) {
        if (t === ignore) continue;
        if (dist(t.x, t.y, x, y) < 30 * this.scale) return false;
      }
      return true;
    }

    canPlace(type, x, y) {
      if (!type) return { ok: false, reason: "No monkey selected." };
      const def = TOWERS[type];
      if (this.money < def.cost) return { ok: false, reason: `Need $${formatMoney(def.cost - this.money)} more.` };
      if (!this.isSpotClear(x, y)) {
        if (this.track.nearest(x, y).distance < this.pathWidth * 0.5 + 13 * this.scale) return { ok: false, reason: "Too close to the track." };
        return { ok: false, reason: "Find a little more open grass." };
      }
      return { ok: true, reason: "" };
    }

    placeStarter() {
      if (this.towers.some((t) => t.isScout)) return;
      const candidates = this.w / this.h < 1.18
        ? [[0.68, 0.29], [0.34, 0.57], [0.7, 0.47], [0.25, 0.31], [0.54, 0.75], [0.47, 0.21]]
        : [[0.5, 0.31], [0.29, 0.5], [0.61, 0.35], [0.77, 0.48], [0.53, 0.68], [0.13, 0.51]];
      let spot = null;
      for (const [nx, ny] of candidates) {
        const x = nx * this.w;
        const y = ny * this.h;
        if (this.isSpotClear(x, y)) {
          spot = { x, y };
          break;
        }
      }
      if (!spot) {
        for (let i = 0; i < 160; i++) {
          const x = rand(0.12, 0.88) * this.w;
          const y = rand(0.12, 0.88) * this.h;
          if (this.isSpotClear(x, y)) {
            spot = { x, y };
            break;
          }
        }
      }
      if (!spot) spot = { x: this.w * 0.5, y: this.h * 0.5 };
      const t = new Tower(this, "dart", spot.x / this.w, spot.y / this.h, { scout: true });
      this.towers.push(t);
      this.dirty = true;
    }

    nudgeTowers() {
      for (const t of this.towers) {
        let x = t.nx * this.w;
        let y = t.ny * this.h;
        if (this.isSpotClear(x, y, t)) continue;
        let found = false;
        for (let ring = 1; ring <= 20 && !found; ring++) {
          const radius = ring * 12 * this.scale;
          for (let i = 0; i < 18; i++) {
            const a = (i / 18) * TAU + ring * 0.35;
            const nx = x + Math.cos(a) * radius;
            const ny = y + Math.sin(a) * radius;
            if (this.isSpotClear(nx, ny, t)) {
              t.nx = nx / this.w;
              t.ny = ny / this.h;
              found = true;
              break;
            }
          }
        }
        if (!found) {
          t.nx = 0.5;
          t.ny = 0.5;
        }
      }
    }

    // -----------------------------------------------------
    // Input helpers
    // -----------------------------------------------------
    setPointer(x, y, inside) {
      this.pointer.x = x;
      this.pointer.y = y;
      this.pointer.inside = inside;
      if (this.selectedType && inside) {
        const check = this.canPlace(this.selectedType, x, y);
        this.ghostValid = check.ok;
        this.ghostReason = check.reason;
      }
      if (!this.selectedType && inside) {
        this.hoveredTower = this.towerAt(x, y);
      } else {
        this.hoveredTower = null;
      }
    }

    towerAt(x, y) {
      let best = null;
      let bestD = 26 * this.scale;
      for (const t of this.towers) {
        const d = dist(t.x, t.y - 18 * this.scale, x, y);
        if (d < bestD) {
          bestD = d;
          best = t;
        }
      }
      return best;
    }

    selectBuild(type) {
      if (this.gameOver || this.paused) return;
      this.selectedTower = null;
      this.selectedType = type === this.selectedType ? null : type;
      if (this.selectedType) {
        this.ghostValid = false;
        if (this.pointer.inside) {
          const check = this.canPlace(this.selectedType, this.pointer.x, this.pointer.y);
          this.ghostValid = check.ok;
          this.ghostReason = check.reason;
        }
      }
      this.dirty = true;
    }

    cancelBuild() {
      this.selectedType = null;
      this.ghostValid = false;
      this.dirty = true;
    }

    selectTower(t) {
      this.selectedType = null;
      this.selectedTower = t;
      this.dirty = true;
    }

    closeInspector() {
      this.selectedTower = null;
      this.dirty = true;
    }

    tryPlace(type, x, y) {
      const check = this.canPlace(type, x, y);
      if (!check.ok) {
        this.sound("error");
        this.emit("toast", check.reason);
        return false;
      }
      const def = TOWERS[type];
      this.money -= def.cost;
      const t = new Tower(this, type, x / this.w, y / this.h);
      this.towers.push(t);
      this.addRing(x, y, 8 * this.scale, 46 * this.scale, "#d7ff8e", 0.55, true);
      this.addParticles(x, y - 10 * this.scale, def.palette.accent, 15, 80 * this.scale, 0.65, "star");
      this.sound("place");
      this.tutorialDismissed = true;
      this.emit("placed", { type });
      this.dirty = true;
      if (this.money < def.cost) this.selectedType = null;
      return true;
    }

    // -----------------------------------------------------
    // Economy / rounds
    // -----------------------------------------------------
    startRound() {
      if (this.roundActive || this.gameOver || this.round >= ROUNDS.length) return false;
      Sound.init();
      this.round++;
      this.roundActive = true;
      this.roundClock = 0;
      this.roundSpawned = 0;
      this.autoTimer = 0;
      this.selectedTower = null;
      this.selectedType = null;
      this.spawnPlan = [];
      const groups = ROUNDS[this.round - 1];
      for (const group of groups) {
        for (let i = 0; i < group.count; i++) {
          this.spawnPlan.push({
            type: group.type,
            at: group.delay + i * group.gap,
            offset: rand(-6, 6) * this.scale
          });
        }
      }
      this.spawnPlan.sort((a, b) => a.at - b.at);
      this.roundTotal = this.spawnPlan.length;
      this.tutorialDismissed = true;
      const boss = groups.some((g) => BLOONS[g.type].big);
      this.emit("roundStart", { round: this.round, groups, boss });
      this.sound("round");
      if (boss) {
        this.sound("boss");
        this.shake = Math.max(this.shake, 8);
      }
      this.dirty = true;
      return true;
    }

    updateRound(dt) {
      if (!this.roundActive) return;
      this.roundClock += dt;
      while (this.spawnPlan.length && this.spawnPlan[0].at <= this.roundClock) {
        const item = this.spawnPlan.shift();
        this.spawnBloon(item.type, 0, item.offset);
        this.roundSpawned++;
      }
    }

    spawnBloon(type, t = 0, offset = 0, opts = {}) {
      if (!BLOONS[type]) return null;
      const b = new Bloon(this, type, t, offset, opts);
      this.bloons.push(b);
      return b;
    }

    checkRoundEnd() {
      if (!this.roundActive || this.gameOver) return;
      if (this.spawnPlan.length || this.bloons.length) return;
      this.roundActive = false;
      const reward = 50 + this.round * 8;
      this.money += reward;
      this.score += reward * 2;
      this.emit("roundComplete", { round: this.round, reward });
      this.sound("upgrade");
      if (this.round >= ROUNDS.length) {
        this.endDelay = 1.9;
      } else if (this.autoStart) {
        this.autoTimer = 4.6;
      }
      this.dirty = true;
    }

    updateAuto(dt) {
      if (this.gameOver || this.roundActive) return;
      if (this.autoStart && this.round > 0 && this.round < ROUNDS.length && this.autoTimer > 0) {
        this.autoTimer -= dt;
        if (this.autoTimer <= 0) {
          this.autoTimer = 0;
          this.startRound();
        }
      }
      if (this.endDelay > 0) {
        this.endDelay -= dt;
        if (this.endDelay <= 0) this.endGame(true);
      }
    }

    endGame(won) {
      if (this.gameOver) return;
      this.gameOver = true;
      this.won = won;
      this.roundActive = false;
      this.autoStart = false;
      this.autoTimer = 0;
      this.selectedType = null;
      this.selectedTower = null;
      this.paused = false;
      if (won) {
        this.sound("win");
        for (let i = 0; i < 90; i++) {
          this.particles.push({
            x: rand(0, this.w),
            y: rand(-this.h * 0.2, this.h * 0.35),
            vx: rand(-30, 30),
            vy: rand(40, 130),
            gravity: 22,
            life: rand(2.2, 4.5),
            maxLife: 4.5,
            size: rand(2.5, 5.5) * this.scale,
            color: BTD.pick(["#ffd45e", "#ff8e70", "#8be66f", "#7fcfff", "#ff9ddc"]),
            kind: "confetti",
            rot: rand(0, TAU),
            vr: rand(-8, 8)
          });
        }
      } else {
        this.sound("lose");
        this.shake = 14;
      }
      this.emit("gameover", {
        won,
        round: this.round,
        pops: this.pops,
        score: Math.round(this.score),
        lives: this.lives,
        money: this.money
      });
      this.dirty = true;
    }

    restart() {
      this.money = 800;
      this.lives = 150;
      this.score = 0;
      this.pops = 0;
      this.round = 0;
      this.roundActive = false;
      this.roundClock = 0;
      this.spawnPlan = [];
      this.roundTotal = 0;
      this.roundSpawned = 0;
      this.autoTimer = 0;
      this.autoStart = false;
      this.endDelay = 0;
      this.gameOver = false;
      this.won = false;
      this.paused = false;
      this.speed = 1;
      this.time = 0;
      this.shake = 0;
      this.hurtFlash = 0;
      this.towers = [];
      this.bloons = [];
      this.projectiles = [];
      this.particles = [];
      this.rings = [];
      this.floaters = [];
      this.tracers = [];
      this.selectedType = null;
      this.selectedTower = null;
      this.hoveredTower = null;
      this.tutorialDismissed = false;
      this.ghostValid = false;
      this.placeStarter();
      this.emit("reset");
      this.dirty = true;
    }

    // -----------------------------------------------------
    // Simulation
    // -----------------------------------------------------
    step(rawDt) {
      if (this.paused || this.gameOver) return;
      this.realTime += rawDt;
      let remaining = Math.min(rawDt, 0.05) * this.speed;
      let iterations = 0;
      while (remaining > 0.0001 && iterations++ < 10) {
        const dt = Math.min(remaining, 1 / 60);
        this.update(dt);
        remaining -= dt;
        if (this.gameOver) break;
      }
    }

    update(dt) {
      this.time += dt;
      this.updateRound(dt);
      if (this.gameOver) return;

      for (const t of [...this.towers]) t.update(dt);
      if (this.selectedTower && !this.towers.includes(this.selectedTower)) this.selectedTower = null;

      for (const p of [...this.projectiles]) {
        p.update(dt);
        if (!p.dead && p.kind !== "bomb") this.collideProjectile(p);
      }

      for (const b of [...this.bloons]) {
        if (!b.dead) b.update(dt);
        if (this.gameOver) break;
      }

      this.bloons = this.bloons.filter((b) => !b.dead);
      this.projectiles = this.projectiles.filter((p) => !p.dead);
      this.updateEffects(dt);
      this.shake = Math.max(0, this.shake - dt * 22);
      this.hurtFlash = Math.max(0, this.hurtFlash - dt * 1.8);
      this.checkRoundEnd();
      this.updateAuto(dt);
    }

    findTarget(tower) {
      const range = tower.range;
      const range2 = range * range;
      const tx = tower.x;
      const ty = tower.y - 20 * this.scale;
      let best = null;
      let bestScore = -Infinity;
      for (const b of this.bloons) {
        if (b.dead) continue;
        const p = b.position();
        const d2 = BTD.dist2(tx, ty, p.x, p.y);
        if (d2 > range2) continue;
        let score;
        switch (TARGET_MODES[tower.mode].key) {
          case "last": score = -b.t; break;
          case "close": score = -d2; break;
          case "strong": score = b.def.rbe * 1000 + b.hp; break;
          default: score = b.t; break;
        }
        if (score > bestScore) {
          bestScore = score;
          best = b;
        }
      }
      return best;
    }

    fireTower(tower, target) {
      const stats = tower.stats;
      const scale = this.scale;
      const p = target.position();
      const ox = tower.x;
      const oy = tower.y - 27 * scale;
      const aim = Math.atan2(p.y - oy, p.x - ox);
      const kind = tower.type;

      if (kind === "dart") {
        const n = Math.max(1, Math.round(stats.shots));
        for (let i = 0; i < n; i++) {
          const a = aim + (i - (n - 1) / 2) * stats.spread;
          this.projectiles.push(new Projectile(this, {
            kind: "dart", x: ox, y: oy, angle: a,
            speed: stats.speed * scale, damage: stats.dmg, pierce: stats.pierce,
            life: 1.35, size: 2.4 * scale, source: tower, color: "#f9e7c2"
          }));
        }
        this.sound("shoot");
      } else if (kind === "tack") {
        const n = Math.round(stats.shots);
        const base = tower.age * 0.25;
        for (let i = 0; i < n; i++) {
          const a = base + (i / n) * TAU;
          this.projectiles.push(new Projectile(this, {
            kind: "tack", x: tower.x, y: tower.y - 19 * scale, angle: a,
            speed: stats.speed * scale, damage: stats.dmg, pierce: stats.pierce,
            life: 0.37, size: 2.2 * scale, source: tower, color: "#eee8d4"
          }));
        }
        this.sound("shoot");
      } else if (kind === "boomerang") {
        this.projectiles.push(new Projectile(this, {
          kind: "boomerang", x: ox, y: oy, angle: aim,
          speed: stats.speed * scale, damage: stats.dmg, pierce: stats.pierce,
          life: 1.65, size: 4.5 * scale, source: tower, color: "#e2a636",
          returning: true, returnAfter: 0.4, spin: 0
        }));
        this.sound("boomerang");
      } else if (kind === "glue") {
        const n = Math.max(1, Math.round(stats.shots));
        for (let i = 0; i < n; i++) {
          const a = aim + (i - (n - 1) / 2) * (stats.spread || 0.04);
          this.projectiles.push(new Projectile(this, {
            kind: "glue", x: ox, y: oy, angle: a,
            speed: stats.speed * scale, damage: 0, pierce: stats.pierce,
            life: 1.2, size: 3.2 * scale, source: tower, color: "#9ad33b",
            slowFactor: stats.slow, slowDuration: stats.duration
          }));
        }
        this.sound("glue");
      } else if (kind === "bomb") {
        const distance = Math.max(20, dist(ox, oy, p.x, p.y));
        const duration = clamp(distance / (stats.speed * scale), 0.35, 1.2);
        this.projectiles.push(new Projectile(this, {
          kind: "bomb", x: ox, y: oy, sx: ox, sy: oy, tx: p.x, ty: p.y,
          duration, age: 0, life: duration + 0.1, z: 0, arc: 55 * scale,
          splash: stats.splash * scale, damage: stats.dmg, source: tower,
          size: 5 * scale, color: "#25232a",
          cluster: tower.specials.has("cluster")
        }));
        this.sound("bomb");
      } else if (kind === "ice") {
        this.icePulse(tower);
      } else if (kind === "sniper") {
        let dmg = stats.dmg;
        const p2 = target.position();
        if (tower.specials.has("cripple") && target.def.big) {
          dmg += 8;
          target.applyGlue(0.55, 2.5);
        }
        this.tracers.push({
          x1: ox, y1: oy, x2: p2.x, y2: p2.y,
          life: 0.14, maxLife: 0.14, color: "#ffe8a3", width: 1.7 * scale
        });
        target.damage(dmg, { kind: "bullet", tower });
        this.addParticles(p2.x, p2.y, "#ffe8a3", 5, 80 * scale, 0.35, "spark");
        this.addParticles(ox, oy, "#ffd08a", 3, 45 * scale, 0.22, "spark");
        this.sound("sniper");
      } else if (kind === "ninja") {
        const n = Math.max(1, Math.round(stats.shots));
        for (let i = 0; i < n; i++) {
          const a = aim + (i - (n - 1) / 2) * (stats.spread || 0.03);
          this.projectiles.push(new Projectile(this, {
            kind: "shuriken", x: ox, y: oy, angle: a,
            speed: stats.speed * scale, damage: stats.dmg, pierce: stats.pierce,
            life: 1.0, size: 4 * scale, source: tower, color: "#d9e0e6", spin: 0
          }));
        }
        this.sound("shoot");
      } else if (kind === "super") {
        const sun = tower.specials.has("sunGod");
        this.projectiles.push(new Projectile(this, {
          kind: sun ? "sun" : "super", x: ox, y: oy, angle: aim,
          speed: stats.speed * scale, damage: stats.dmg, pierce: 1,
          life: 0.75, size: (sun ? 6 : 3.4) * scale, source: tower,
          color: sun ? "#ffd45e" : "#ffe8f0",
          splash: sun ? stats.splash * scale : 0,
          isBig: sun
        }));
        this.sound("shoot");
      }
    }

    icePulse(tower) {
      const stats = tower.stats;
      const scale = this.scale;
      let range = stats.range * scale;
      if (tower.specials.has("absoluteZero")) range *= 1.16;
      this.addRing(tower.x, tower.y, 9 * scale, range, "#c5f9ff", 0.55, true);
      this.addRing(tower.x, tower.y, 4 * scale, range * 0.82, "#e8ffff", 0.42, false);
      const snap = [...this.bloons];
      for (const b of snap) {
        if (b.dead) continue;
        const p = b.position();
        if (dist(tower.x, tower.y, p.x, p.y) <= range + b.radius) {
          b.damage(stats.dmg || 0, { kind: "ice", tower });
          if (!b.dead) {
            b.freeze(stats.freeze);
            if (stats.slowAfter) b.applyGlue(0.52, stats.freeze + stats.slowAfter);
            this.addParticles(p.x, p.y, "#c9f9ff", 4, 55 * scale, 0.45, "ice");
          }
        }
      }
      this.addParticles(tower.x, tower.y - 24 * scale, "#d7ffff", 18, 100 * scale, 0.7, "ice");
      this.sound("freeze");
    }

    ringOfFire(tower) {
      const range = tower.range * 1.04;
      this.addRing(tower.x, tower.y, 8 * this.scale, range, "#ffb13b", 0.38, true);
      this.addParticles(tower.x, tower.y - 14 * this.scale, "#ff9e2f", 8, 100 * this.scale, 0.45, "fire");
      const snap = [...this.bloons];
      for (const b of snap) {
        if (b.dead) continue;
        const p = b.position();
        if (dist(tower.x, tower.y, p.x, p.y) <= range + b.radius) {
          b.damage(tower.stats.dmg || 1, { kind: "fire", tower });
        }
      }
      if (Math.random() < 0.45) this.sound("bomb");
    }

    collideProjectile(p) {
      const snap = this.bloons;
      for (const b of snap) {
        if (b.dead || p.dead) continue;
        if (p.hitSet.has(b.id)) continue;
        const bp = b.position();
        const rr = b.radius + (p.size || 3);
        if (BTD.dist2(p.x, p.y, bp.x, bp.y) > rr * rr) continue;

        p.hitSet.add(b.id);
        if (p.kind === "sun" && p.splash) {
          p.dead = true;
          this.explode(p.x, p.y, p.splash, p.damage, p.source, { sun: true });
          return;
        }
        if (p.kind === "glue") {
          b.applyGlue(p.slowFactor, p.slowDuration);
          this.addParticles(bp.x, bp.y, "#9ad33b", 4, 45 * this.scale, 0.42, "goo");
        } else {
          b.damage(p.damage, { kind: p.kind === "super" ? "energy" : "projectile", tower: p.source });
        }
        this.addParticles(bp.x, bp.y, p.color || "#fff", 3, 55 * this.scale, 0.28, "spark");
        p.pierce--;
        if (p.pierce <= 0) {
          p.dead = true;
          return;
        }
      }
    }

    explode(x, y, radius, damage, tower, opts = {}) {
      this.addRing(x, y, 7 * this.scale, radius * (opts.sun ? 1.5 : 1.25), opts.sun ? "#ffe37a" : "#ffb04a", 0.5, true);
      this.addParticles(x, y, opts.sun ? "#ffe37a" : "#ff9c3b", opts.sun ? 20 : 13, 120 * this.scale, 0.65, opts.sun ? "fire" : "smoke");
      this.addParticles(x, y, "#40342c", 6, 60 * this.scale, 0.85, "smoke");
      this.shake = Math.max(this.shake, opts.sun ? 4 : 3);
      this.sound("bomb");
      const snap = [...this.bloons];
      for (const b of snap) {
        if (b.dead) continue;
        const p = b.position();
        if (dist(x, y, p.x, p.y) <= radius + b.radius) {
          b.damage(damage, { kind: "explosion", tower });
        }
      }
      if (opts.cluster && !opts.noCluster) {
        for (let i = 0; i < 3; i++) {
          const a = (i / 3) * TAU + 0.4;
          const cx = x + Math.cos(a) * radius * 0.72;
          const cy = y + Math.sin(a) * radius * 0.55;
          this.explode(cx, cy, radius * 0.48, Math.max(1, Math.floor(damage * 0.55)), tower, { noCluster: true, sun: false });
        }
      }
    }

    onBloonPopped(b) {
      const p = b.position();
      const def = b.def;
      this.pops++;
      this.score += def.score;
      this.money += def.cash;
      const scale = this.scale;
      this.addParticles(p.x, p.y, def.light, b.big ? 28 : 6, (b.big ? 160 : 75) * scale, b.big ? 1.1 : 0.48, "dot");
      this.addParticles(p.x, p.y, def.color, b.big ? 16 : 3, (b.big ? 130 : 55) * scale, 0.38, "spark");
      if (b.big) {
        this.addRing(p.x, p.y, 8, b.radius * 3.2, def.light, 0.65, true);
        this.addFloater(p.x, p.y - b.radius, `${def.label} POPPED!`, "#ffe27d", 1.4, 16);
        this.shake = Math.max(this.shake, 9);
        this.sound("bigPop");
        this.emit("bossPop", { type: b.type });
      } else {
        this.sound("pop", BLOONS[b.type].rbe);
        if (def.cash >= 4) this.addFloater(p.x, p.y - 8, `+$${def.cash}`, "#ffe27d", 0.75, 10);
      }
      this.dirty = true;
    }

    onLeak(b, p) {
      const leak = b.def.leak;
      this.lives = Math.max(0, this.lives - leak);
      this.hurtFlash = Math.min(1, this.hurtFlash + 0.7);
      this.shake = Math.max(this.shake, 7);
      this.addFloater(p.x, p.y - 12, `-${leak}`, "#ff7d6f", 1.1, 15);
      this.addRing(p.x, p.y, 8, 60 * this.scale, "#ff5b4d", 0.55, true);
      this.sound("life");
      this.emit("leak", { amount: leak, lives: this.lives });
      this.dirty = true;
      if (this.lives <= 0) this.endGame(false);
    }

    // -----------------------------------------------------
    // Effects
    // -----------------------------------------------------
    addParticles(x, y, color, count = 6, speed = 60, life = 0.55, kind = "dot") {
      for (let i = 0; i < count; i++) {
        const a = rand(0, TAU);
        const v = speed * rand(0.25, 1);
        const l = life * rand(0.65, 1.25);
        this.particles.push({
          x, y,
          vx: Math.cos(a) * v,
          vy: Math.sin(a) * v - (kind === "smoke" ? rand(8, 25) : 0),
          gravity: kind === "confetti" ? 25 : kind === "smoke" ? -8 : 120,
          life: l,
          maxLife: l,
          size: rand(1.4, 3.7) * this.scale * (kind === "smoke" ? 2.1 : kind === "star" ? 1.7 : 1),
          color,
          kind,
          rot: rand(0, TAU),
          vr: rand(-8, 8)
        });
      }
      if (this.particles.length > 600) this.particles.splice(0, this.particles.length - 600);
    }

    addRing(x, y, r, maxR, color, life = 0.5, fill = false) {
      this.rings.push({ x, y, r, maxR, color, life, maxLife: life, fill });
      if (this.rings.length > 60) this.rings.shift();
    }

    addFloater(x, y, text, color = "#fff", life = 0.9, size = 11) {
      this.floaters.push({ x, y, text, color, life, maxLife: life, size });
      if (this.floaters.length > 70) this.floaters.shift();
    }

    updateEffects(dt) {
      for (const p of this.particles) {
        p.life -= dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vy += p.gravity * dt;
        p.vx *= kindDrag(p.kind, dt);
        p.rot += p.vr * dt;
        if (p.kind === "smoke") p.size += dt * 14 * this.scale;
      }
      this.particles = this.particles.filter((p) => p.life > 0);
      for (const r of this.rings) r.life -= dt;
      this.rings = this.rings.filter((r) => r.life > 0);
      for (const f of this.floaters) {
        f.life -= dt;
        f.y -= dt * 24 * this.scale;
      }
      this.floaters = this.floaters.filter((f) => f.life > 0);
      for (const t of this.tracers) t.life -= dt;
      this.tracers = this.tracers.filter((t) => t.life > 0);
    }

    sound(name, pitch) {
      Sound.play(name, pitch);
    }

    emit(name, data) {
      const fn = this.hooks[name];
      if (fn) fn(data);
    }
  }

  function kindDrag(kind, dt) {
    if (kind === "spark" || kind === "ice") return Math.max(0, 1 - dt * 1.8);
    if (kind === "smoke") return Math.max(0, 1 - dt * 1.1);
    if (kind === "confetti") return Math.max(0, 1 - dt * 0.25);
    return Math.max(0, 1 - dt * 0.6);
  }

  BTD.Game = Game;
  BTD.describeRound = function (round) {
    const groups = ROUNDS[round - 1];
    if (!groups) return "";
    const totals = new Map();
    for (const g of groups) totals.set(g.type, (totals.get(g.type) || 0) + g.count);
    return [...totals.entries()].map(([type, n]) => `${n} ${BLOONS[type].label.toLowerCase()}${n === 1 ? "" : "s"}`).join(", ");
  };
})();

/* =========================================================
   BLOONS TD 5 — SUNSET GROVE
   Canvas rendering: scenery, characters, effects.
   ========================================================= */
(() => {
  "use strict";
  const BTD = (window.BTD = window.BTD || {});
  const { TAU, clamp, lerp } = BTD;
  const { Art, WorldArt } = BTD;
  const { ellipse } = Art;

  Game.prototype.renderBackground = function (ctx) {
    const { w, h, scale, pathWidth } = this;
    const rng = BTD.makeRng(7301 + Math.round(w + h * 3));

    // Base grass wash
    const grass = ctx.createLinearGradient(0, 0, 0, h);
    grass.addColorStop(0, "#73b854");
    grass.addColorStop(0.4, "#65aa49");
    grass.addColorStop(1, "#4e913c");
    ctx.fillStyle = grass;
    ctx.fillRect(0, 0, w, h);

    // Warm sunlight pooling in the top-left
    const sunlight = ctx.createRadialGradient(w * 0.12, h * 0.05, 10, w * 0.12, h * 0.05, Math.max(w, h) * 0.65);
    sunlight.addColorStop(0, "rgba(255, 244, 160, .28)");
    sunlight.addColorStop(0.38, "rgba(255, 220, 115, .09)");
    sunlight.addColorStop(1, "rgba(255, 220, 115, 0)");
    ctx.fillStyle = sunlight;
    ctx.fillRect(0, 0, w, h);

    // Soft tonal patches
    for (let i = 0; i < 18; i++) {
      const x = rng() * w;
      const y = rng() * h;
      const r = (40 + rng() * 140) * scale;
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      const dark = rng() < 0.5;
      g.addColorStop(0, dark ? "rgba(38, 94, 34, .11)" : "rgba(196, 231, 116, .1)");
      g.addColorStop(1, "rgba(255,255,255,0)");
      ctx.fillStyle = g;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }

    // Fine grass texture
    ctx.lineCap = "round";
    for (let i = 0; i < 620; i++) {
      const x = rng() * w;
      const y = rng() * h;
      const len = (1.5 + rng() * 4) * scale;
      ctx.strokeStyle = rng() < 0.5 ? `rgba(42, 103, 38, ${0.08 + rng() * 0.12})` : `rgba(195, 230, 122, ${0.07 + rng() * 0.1})`;
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (rng() - 0.5) * 2.5, y - len);
      ctx.stroke();
    }

    // Pond before the track
    if (this.pond) {
      WorldArt.drawPond(ctx, this.pond.x, this.pond.y, this.pond.rx, this.pond.ry, rng);
      // Soggy bank
      ctx.strokeStyle = "rgba(104, 89, 42, .24)";
      ctx.lineWidth = 8 * scale;
      ctx.beginPath();
      ctx.ellipse(this.pond.x, this.pond.y, this.pond.rx + 1, this.pond.ry + 1, -0.08, 0, TAU);
      ctx.stroke();
    }

    // Dirt track
    this.track.draw(ctx, pathWidth, scale);

    // Grass tufts that hug the path edges
    for (let i = 0; i < 46; i++) {
      const t = rng();
      const p = this.track.pointAt(t);
      const side = rng() < 0.5 ? -1 : 1;
      const off = (pathWidth * 0.5 + (2 + rng() * 5) * scale) * side;
      WorldArt.drawGrassTuft(ctx, p.x + p.nx * off, p.y + p.ny * off, 0.7 + rng() * 0.65, rng, side < 0);
    }

    // Small ground clutter
    for (const f of this.scenery.flowers) WorldArt.drawFlower(ctx, f.x, f.y, f.s, rng);
    for (const g of this.scenery.grass) WorldArt.drawGrassTuft(ctx, g.x, g.y, g.s, rng, g.flip);
    for (const m of this.scenery.mushrooms) WorldArt.drawMushroom(ctx, m.x, m.y, m.s, rng);

    // Larger scenery sorted by depth
    const decor = [];
    for (const b of this.scenery.bushes) decor.push({ y: b.y, kind: "bush", item: b });
    for (const r of this.scenery.rocks) decor.push({ y: r.y, kind: "rock", item: r });
    for (const t of this.scenery.trees) decor.push({ y: t.y, kind: "tree", item: t });
    decor.sort((a, b) => a.y - b.y);
    for (const d of decor) {
      if (d.kind === "tree") {
        WorldArt.drawTree(ctx, d.item.x, d.item.y, d.item.s * scale, rng, d.item.palm);
      } else if (d.kind === "bush") {
        WorldArt.drawBush(ctx, d.item.x, d.item.y, d.item.s * scale, rng, d.item.berries);
      } else {
        WorldArt.drawRock(ctx, d.item.x, d.item.y, d.item.s * scale, rng);
      }
    }

    // Start sign and exit gate
    if (this.scenery.sign) {
      const s = this.scenery.sign;
      WorldArt.drawSign(ctx, s.x, s.y, clamp(0.88 * scale, 0.62, 1.25), "START");
    }
    if (this.scenery.gate) {
      const g = this.scenery.gate;
      WorldArt.drawGate(ctx, g.x, g.y, clamp(0.92 * scale, 0.65, 1.3));
    }

    // Framing shade
    const edge = ctx.createRadialGradient(w * 0.5, h * 0.48, Math.min(w, h) * 0.35, w * 0.5, h * 0.48, Math.max(w, h) * 0.8);
    edge.addColorStop(0, "rgba(15, 39, 16, 0)");
    edge.addColorStop(0.72, "rgba(15, 39, 16, .08)");
    edge.addColorStop(1, "rgba(8, 27, 11, .34)");
    ctx.fillStyle = edge;
    ctx.fillRect(0, 0, w, h);

    // Top-left sun haze
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    ctx.globalAlpha = 0.16;
    ctx.fillStyle = "#fff4a5";
    ctx.beginPath();
    ctx.arc(w * 0.09, h * 0.02, 90 * scale, 0, TAU);
    ctx.fill();
    ctx.restore();
  };

  Game.prototype.renderAmbient = function (ctx, now) {
    const { w, h, scale, time } = this;
    const t = now / 1000;

    // Moving sunbeams
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    for (let i = 0; i < 4; i++) {
      const sway = Math.sin(t * 0.08 + i) * 25;
      const x = w * (0.05 + i * 0.2) + sway;
      const grad = ctx.createLinearGradient(x, 0, x + 140 * scale, h * 0.75);
      grad.addColorStop(0, "rgba(255, 245, 175, .09)");
      grad.addColorStop(0.6, "rgba(255, 232, 125, .03)");
      grad.addColorStop(1, "rgba(255, 232, 125, 0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(x - 55 * scale, 0);
      ctx.lineTo(x + 75 * scale, 0);
      ctx.lineTo(x + 240 * scale, h * 0.8);
      ctx.lineTo(x + 40 * scale, h * 0.8);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // Pond shimmer
    if (this.pond) {
      const p = this.pond;
      ctx.save();
      ctx.strokeStyle = "rgba(205, 255, 247, .22)";
      ctx.lineWidth = 1.1;
      for (let i = 0; i < 3; i++) {
        const moving = (t * (9 + i * 3) + i * 35) % (p.rx * 1.3);
        ctx.beginPath();
        ctx.ellipse(p.x - p.rx * 0.6 + moving, p.y - p.ry * 0.15 + i * p.ry * 0.18, p.rx * 0.16, 1.4, 0, 0, TAU);
        ctx.stroke();
      }
      ctx.restore();
    }

    // Torches
    if (this.scenery.torches) {
      for (const torch of this.scenery.torches) {
        WorldArt.drawTorch(ctx, torch.x, torch.y, clamp(0.9 * scale, 0.65, 1.25), t);
      }
    }

    // Butterflies
    for (const b of this.butterflies) {
      const x = b.x + Math.sin(t * b.speed + b.phase) * b.range;
      const y = b.y + Math.cos(t * b.speed * 0.73 + b.phase * 1.7) * b.range * 0.35;
      WorldArt.drawButterfly(ctx, x, y, clamp(scale * 0.9, 0.58, 1.1), t, b.phase, b.color);
    }

    // Drifting leaves
    for (const leaf of this.leaves) {
      const x = (leaf.x + t * leaf.speed + Math.sin(t * 0.6 + leaf.phase) * 18) % (w + 40) - 20;
      const y = (leaf.y + t * leaf.speed * 0.33 + Math.cos(t * 0.5 + leaf.phase) * 10) % (h + 40) - 20;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(t * 0.7 + leaf.phase);
      ctx.fillStyle = "rgba(184, 222, 104, .24)";
      ctx.beginPath();
      ctx.ellipse(0, 0, leaf.size * scale, leaf.size * 0.48 * scale, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // Floating pollen
    ctx.save();
    for (const m of this.motes) {
      const x = m.x + Math.sin(t * m.speed + m.phase) * 26;
      const y = m.y + Math.cos(t * m.speed * 0.8 + m.phase * 2) * 18;
      ctx.globalAlpha = 0.22 + Math.sin(t * 2 + m.phase) * 0.12;
      ctx.fillStyle = "#fff6bf";
      ctx.beginPath();
      ctx.arc(x, y, m.size * scale, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  };

  Game.prototype.render = function (now) {
    const ctx = this.ctx;
    const { w, h, dpr } = this;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = "#2b522a";
    ctx.fillRect(0, 0, w, h);

    const shakeX = this.shake > 0.2 ? (Math.random() - 0.5) * this.shake : 0;
    const shakeY = this.shake > 0.2 ? (Math.random() - 0.5) * this.shake * 0.65 : 0;

    ctx.save();
    ctx.translate(shakeX, shakeY);

    if (this.background) ctx.drawImage(this.background, 0, 0, w, h);
    this.renderAmbient(ctx, now);
    this.drawRings(ctx);
    this.drawRanges(ctx);

    const items = [];
    for (const t of this.towers) items.push({ y: t.y, type: "tower", item: t });
    for (const b of this.bloons) {
      if (!b.dead) {
        const p = b.position();
        items.push({ y: p.y, type: "bloon", item: b });
      }
    }
    items.sort((a, b) => a.y - b.y);
    for (const entry of items) {
      if (entry.type === "tower") this.drawTower(ctx, entry.item, now);
      else this.drawBloon(ctx, entry.item, now);
    }

    this.drawProjectiles(ctx, now);
    this.drawTracers(ctx);
    this.drawParticles(ctx);
    this.drawFloaters(ctx);
    this.drawGhost(ctx, now);
    ctx.restore();

    // Edge damage pulse
    if (this.hurtFlash > 0.01) {
      const hurt = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.24, w / 2, h / 2, Math.max(w, h) * 0.72);
      hurt.addColorStop(0, "rgba(255, 51, 28, 0)");
      hurt.addColorStop(0.72, `rgba(255, 44, 25, ${this.hurtFlash * 0.12})`);
      hurt.addColorStop(1, `rgba(208, 24, 12, ${this.hurtFlash * 0.5})`);
      ctx.fillStyle = hurt;
      ctx.fillRect(0, 0, w, h);
    }

    // Subtle vignette
    const vig = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.42, w / 2, h / 2, Math.max(w, h) * 0.82);
    vig.addColorStop(0, "rgba(8, 25, 11, 0)");
    vig.addColorStop(1, "rgba(5, 19, 8, .22)");
    ctx.fillStyle = vig;
    ctx.fillRect(0, 0, w, h);
  };

  Game.prototype.drawRanges = function (ctx) {
    const selected = this.selectedTower;
    if (selected && this.towers.includes(selected)) {
      const r = selected.range;
      ctx.save();
      ctx.beginPath();
      ctx.arc(selected.x, selected.y, r, 0, TAU);
      ctx.fillStyle = "rgba(180, 255, 131, .055)";
      ctx.fill();
      ctx.setLineDash([6 * this.scale, 6 * this.scale]);
      ctx.lineWidth = 1.4 * this.scale;
      ctx.strokeStyle = "rgba(201, 255, 153, .5)";
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.beginPath();
      ctx.arc(selected.x, selected.y, 24 * this.scale, 0, TAU);
      ctx.strokeStyle = "rgba(255, 213, 82, .5)";
      ctx.lineWidth = 2 * this.scale;
      ctx.stroke();
      ctx.restore();
    }

    if (this.selectedType && this.pointer.inside) {
      const def = BTD.TOWERS[this.selectedType];
      if (def) {
        const x = this.pointer.x;
        const y = this.pointer.y;
        const r = def.base.range * this.scale;
        const check = this.canPlace(this.selectedType, x, y);
        const color = check.ok ? "149, 255, 108" : "255, 96, 79";
        ctx.save();
        ctx.beginPath();
        ctx.arc(x, y, r, 0, TAU);
        ctx.fillStyle = `rgba(${color}, .065)`;
        ctx.fill();
        ctx.setLineDash([5 * this.scale, 6 * this.scale]);
        ctx.lineWidth = 1.35 * this.scale;
        ctx.strokeStyle = `rgba(${color}, .62)`;
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.arc(x, y, 18 * this.scale, 0, TAU);
        ctx.fillStyle = `rgba(${color}, .12)`;
        ctx.fill();
        ctx.strokeStyle = `rgba(${color}, .75)`;
        ctx.lineWidth = 1.5 * this.scale;
        ctx.stroke();
        if (check.ok) {
          ctx.beginPath();
          ctx.arc(x, y, 25 * this.scale, 0, TAU);
          ctx.strokeStyle = "rgba(255, 220, 100, .25)";
          ctx.stroke();
        }
        ctx.restore();
      }
    }
  };

  Game.prototype.drawRings = function (ctx) {
    for (const r of this.rings) {
      const progress = 1 - r.life / r.maxLife;
      const radius = lerp(r.r, r.maxR, Math.min(1, progress * 1.15));
      const alpha = Math.max(0, r.life / r.maxLife) * 0.72;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.beginPath();
      ctx.arc(r.x, r.y, radius, 0, TAU);
      if (r.fill) {
        ctx.fillStyle = r.color;
        ctx.globalAlpha = alpha * 0.1;
        ctx.fill();
        ctx.globalAlpha = alpha;
      }
      ctx.strokeStyle = r.color;
      ctx.lineWidth = Math.max(1, 3 * this.scale * (r.life / r.maxLife));
      ctx.stroke();
      ctx.restore();
    }
  };

  Game.prototype.drawTower = function (ctx, tower, now) {
    const type = tower.type;
    const scale = this.scale;
    const pop = 1 + Math.sin(clamp(tower.placeAnim / 0.5, 0, 1) * Math.PI) * 0.12;

    // Ring of fire aura
    if (tower.specials.has("ringOfFire")) {
      const r = tower.range * 1.04;
      ctx.save();
      ctx.translate(tower.x, tower.y);
      ctx.rotate(tower.age * 0.65);
      ctx.globalAlpha = 0.36;
      ctx.strokeStyle = "#ffb23f";
      ctx.lineWidth = 3.5 * scale;
      ctx.setLineDash([12 * scale, 9 * scale]);
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, TAU);
      ctx.stroke();
      ctx.setLineDash([]);
      const glow = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
      glow.addColorStop(0, "rgba(255, 140, 30, 0)");
      glow.addColorStop(0.86, "rgba(255, 126, 21, .06)");
      glow.addColorStop(1, "rgba(255, 193, 61, .14)");
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    if (tower.specials.has("sunGod")) {
      const glow = ctx.createRadialGradient(tower.x, tower.y - 25 * scale, 2, tower.x, tower.y - 25 * scale, 48 * scale);
      glow.addColorStop(0, "rgba(255, 231, 123, .28)");
      glow.addColorStop(1, "rgba(255, 211, 75, 0)");
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(tower.x, tower.y - 25 * scale, 48 * scale, 0, TAU);
      ctx.fill();
    }

    ctx.save();
    ctx.translate(tower.x, tower.y);
    if (tower.flash > 0) {
      ctx.globalAlpha = 0.9;
    }
    Art.drawMonkey(ctx, type, scale * pop, now / 1000, tower.aim, tower.level, tower.seed);
    ctx.restore();

    if (tower === this.selectedTower) {
      ctx.save();
      const bob = Math.sin(now / 320) * 2 * scale;
      ctx.fillStyle = "#ffe173";
      ctx.beginPath();
      ctx.moveTo(tower.x, tower.y - 65 * scale + bob);
      ctx.lineTo(tower.x - 5 * scale, tower.y - 73 * scale + bob);
      ctx.lineTo(tower.x + 5 * scale, tower.y - 73 * scale + bob);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  };

  Game.prototype.drawBloon = function (ctx, b, now) {
    const p = b.position();
    const frozen = b.freezeUntil > this.time;
    const glued = b.slowUntil > this.time;
    Art.drawBloon(ctx, p.x, p.y, b.type, this.scale, now / 1000, b.phase, {
      frozen,
      glued,
      flash: b.flash,
      hpRatio: b.big ? clamp(b.hp / b.def.hp, 0, 1) : undefined
    });
  };

  Game.prototype.drawProjectiles = function (ctx, now) {
    const scale = this.scale;
    for (const p of this.projectiles) {
      // Trail
      ctx.save();
      for (let i = 0; i < p.trail.length; i++) {
        const tr = p.trail[i];
        const a = Math.max(0, tr.life / 0.14);
        if (a <= 0) continue;
        ctx.globalAlpha = a * 0.28;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(tr.x, tr.y - (p.kind === "bomb" ? p.z || 0 : 0), Math.max(0.6, (p.size || 2) * 0.5 * (i / p.trail.length)), 0, TAU);
        ctx.fill();
      }
      ctx.restore();

      if (p.kind === "bomb") {
        const altitude = p.z || 0;
        ctx.save();
        ctx.fillStyle = "rgba(28, 43, 18, .25)";
        ellipse(ctx, p.x, p.y, 6 * scale, 2.4 * scale);
        ctx.translate(p.x, p.y - altitude);
        const trailT = clamp(p.age / p.duration, 0, 1);
        ctx.globalAlpha = 1 - trailT * 0.25;
        ctx.fillStyle = "#252329";
        ctx.beginPath();
        ctx.arc(0, 0, 5 * scale, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = "rgba(255,255,255,.15)";
        ctx.lineWidth = 0.9;
        ctx.stroke();
        ctx.fillStyle = "#ffd15f";
        ctx.beginPath();
        ctx.arc(4 * scale, -4.5 * scale, 1.8 * scale, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = "#8b6234";
        ctx.lineWidth = 1.2 * scale;
        ctx.beginPath();
        ctx.moveTo(1 * scale, -4 * scale);
        ctx.quadraticCurveTo(4 * scale, -8 * scale, 6 * scale, -4 * scale);
        ctx.stroke();
        ctx.restore();
        continue;
      }

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.angle);
      if (p.kind === "dart") {
        ctx.strokeStyle = "#f6e8c9";
        ctx.lineWidth = 1.6 * scale;
        ctx.beginPath();
        ctx.moveTo(-7 * scale, 0);
        ctx.lineTo(9 * scale, 0);
        ctx.stroke();
        ctx.fillStyle = "#fdf7e9";
        ctx.beginPath();
        ctx.moveTo(12 * scale, 0);
        ctx.lineTo(7 * scale, -2 * scale);
        ctx.lineTo(7 * scale, 2 * scale);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = "#e15b3f";
        ctx.beginPath();
        ctx.moveTo(-7 * scale, 0);
        ctx.lineTo(-11 * scale, -2.5 * scale);
        ctx.lineTo(-5 * scale, -0.8 * scale);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(-7 * scale, 0);
        ctx.lineTo(-11 * scale, 2.5 * scale);
        ctx.lineTo(-5 * scale, 0.8 * scale);
        ctx.closePath();
        ctx.fill();
      } else if (p.kind === "tack") {
        ctx.fillStyle = "#ddd8c6";
        ctx.beginPath();
        ctx.moveTo(4 * scale, 0);
        ctx.lineTo(-3 * scale, -2.4 * scale);
        ctx.lineTo(-2 * scale, 0);
        ctx.lineTo(-3 * scale, 2.4 * scale);
        ctx.closePath();
        ctx.fill();
      } else if (p.kind === "boomerang") {
        ctx.rotate(p.spin);
        ctx.strokeStyle = "#9a5a21";
        ctx.lineWidth = 4.8 * scale;
        ctx.beginPath();
        ctx.moveTo(-7 * scale, -2 * scale);
        ctx.quadraticCurveTo(3 * scale, -8 * scale, 9 * scale, 2 * scale);
        ctx.stroke();
        ctx.strokeStyle = "#f0b84b";
        ctx.lineWidth = 2.3 * scale;
        ctx.beginPath();
        ctx.moveTo(-6 * scale, -2.5 * scale);
        ctx.quadraticCurveTo(2 * scale, -6.7 * scale, 8 * scale, 1 * scale);
        ctx.stroke();
      } else if (p.kind === "glue") {
        ctx.fillStyle = "#8dcb34";
        ctx.beginPath();
        ctx.ellipse(0, 0, 4.4 * scale, 3.2 * scale, 0, 0, TAU);
        ctx.fill();
        ctx.fillStyle = "rgba(233, 255, 167, .75)";
        ellipse(ctx, -1 * scale, -1 * scale, 1.4 * scale, 0.9 * scale);
      } else if (p.kind === "shuriken") {
        ctx.rotate(p.age * 18);
        ctx.fillStyle = "#d8dfe4";
        Art.star(ctx, 0, 0, 5.2 * scale, 4);
        ctx.fillStyle = "#79828a";
        Art.star(ctx, 0, 0, 2.1 * scale, 4);
      } else if (p.kind === "super" || p.kind === "sun") {
        const radius = (p.kind === "sun" ? 11 : 7) * scale;
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);
        grad.addColorStop(0, "#fffbed");
        grad.addColorStop(0.28, p.kind === "sun" ? "#ffe06a" : "#ffbacd");
        grad.addColorStop(0.6, p.kind === "sun" ? "rgba(255, 152, 38, .7)" : "rgba(255, 118, 162, .5)");
        grad.addColorStop(1, "rgba(255, 130, 80, 0)");
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, TAU);
        ctx.fill();
        ctx.fillStyle = "#fffef5";
        ctx.beginPath();
        ctx.arc(0, 0, (p.kind === "sun" ? 3.5 : 2.2) * scale, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  };

  Game.prototype.drawTracers = function (ctx) {
    for (const t of this.tracers) {
      const a = t.life / t.maxLife;
      ctx.save();
      ctx.globalAlpha = a;
      const grad = ctx.createLinearGradient(t.x1, t.y1, t.x2, t.y2);
      grad.addColorStop(0, "rgba(255, 255, 225, .95)");
      grad.addColorStop(0.7, "rgba(255, 230, 128, .75)");
      grad.addColorStop(1, "rgba(255, 190, 80, 0)");
      ctx.strokeStyle = grad;
      ctx.lineWidth = t.width;
      ctx.beginPath();
      ctx.moveTo(t.x1, t.y1);
      ctx.lineTo(t.x2, t.y2);
      ctx.stroke();
      ctx.restore();
    }
  };

  Game.prototype.drawParticles = function (ctx) {
    for (const p of this.particles) {
      const a = clamp(p.life / p.maxLife, 0, 1);
      ctx.save();
      ctx.globalAlpha = a;
      if (p.kind === "smoke") {
        ctx.fillStyle = p.color;
        ctx.globalAlpha = a * 0.22;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (2 - a * 0.7), 0, TAU);
        ctx.fill();
      } else if (p.kind === "spark") {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = Math.max(0.7, p.size * 0.55);
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - p.vx * 0.025, p.y - p.vy * 0.025);
        ctx.stroke();
      } else if (p.kind === "ice") {
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        Art.star(ctx, 0, 0, p.size, 6);
      } else if (p.kind === "star") {
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        Art.star(ctx, 0, 0, p.size * 1.15);
      } else if (p.kind === "fire") {
        const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.size * 2.4);
        grad.addColorStop(0, "#fff7ba");
        grad.addColorStop(0.35, p.color);
        grad.addColorStop(1, "rgba(255, 77, 10, 0)");
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * 2.4, 0, TAU);
        ctx.fill();
      } else if (p.kind === "confetti") {
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size, -p.size * 0.45, p.size * 2, p.size * 0.9);
      } else if (p.kind === "goo") {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, p.size, p.size * 0.8, p.rot, 0, TAU);
        ctx.fill();
      } else {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * a, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  };

  Game.prototype.drawFloaters = function (ctx) {
    for (const f of this.floaters) {
      const a = clamp(f.life / f.maxLife, 0, 1);
      const pop = 1 + Math.sin((1 - a) * Math.PI) * 0.1;
      ctx.save();
      ctx.globalAlpha = Math.min(1, a * 1.6);
      ctx.translate(f.x, f.y);
      ctx.scale(pop, pop);
      ctx.font = `900 ${Math.max(8, f.size * this.scale)}px "Trebuchet MS", sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.lineWidth = Math.max(2, 3 * this.scale);
      ctx.strokeStyle = "rgba(18, 31, 15, .72)";
      ctx.strokeText(f.text, 0, 0);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, 0, 0);
      ctx.restore();
    }
  };

  Game.prototype.drawGhost = function (ctx, now) {
    if (!this.selectedType || !this.pointer.inside) return;
    const x = this.pointer.x;
    const y = this.pointer.y;
    const check = this.canPlace(this.selectedType, x, y);
    const scale = this.scale;
    ctx.save();
    ctx.globalAlpha = check.ok ? 0.68 : 0.38;
    Art.drawMonkey(ctx, this.selectedType, scale, now / 1000, -1.2, 0, 0.4);
    // The art above is drawn at the origin, so redo it translated.
    ctx.restore();

    // Correctly translated translucent preview
    ctx.save();
    ctx.globalAlpha = check.ok ? 0.72 : 0.42;
    ctx.translate(x, y);
    Art.drawMonkey(ctx, this.selectedType, scale, now / 1000, -1.2, 0, 0.4);
    if (!check.ok) {
      ctx.globalCompositeOperation = "source-atop";
      ctx.fillStyle = "rgba(255, 52, 35, .4)";
      ctx.fillRect(-40 * scale, -70 * scale, 80 * scale, 72 * scale);
    }
    ctx.restore();

    ctx.save();
    ctx.strokeStyle = check.ok ? "rgba(197, 255, 169, .86)" : "rgba(255, 112, 91, .88)";
    ctx.lineWidth = 2 * scale;
    ctx.setLineDash([5 * scale, 4 * scale]);
    ctx.beginPath();
    ctx.arc(x, y, 21 * scale, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    if (!check.ok) {
      ctx.strokeStyle = "rgba(255, 91, 72, .9)";
      ctx.lineWidth = 2 * scale;
      ctx.beginPath();
      ctx.moveTo(x - 5 * scale, y - 30 * scale);
      ctx.lineTo(x + 5 * scale, y - 20 * scale);
      ctx.moveTo(x + 5 * scale, y - 30 * scale);
      ctx.lineTo(x - 5 * scale, y - 20 * scale);
      ctx.stroke();
    }
    ctx.restore();
  };

  // keep the linter honest about the helper that is intentionally shared
  void ellipse;
})();

