import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1100, height: 800 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);

const log = (label, value) => console.log(label, JSON.stringify(value));

// Find a valid grass spot near the track.
const spot = await page.evaluate(() => {
  const g = window.BTD.game;
  for (let r = 355; r > 76; r -= 8) {
    for (let x = 40; x < innerWidth - 40; x += 10) {
      const y = r;
      if (g.canPlace('tack', x, y - 76).ok) return { x, y };
    }
  }
  return null;
});
log('spot', spot);

// Buy a Tack Shooter through the real UI.
await page.locator('.tower-card[data-type="tack"]').click();
await page.mouse.click(spot.x, spot.y);
await page.waitForTimeout(300);
log('after place', await page.evaluate(() => {
  const g = window.BTD.game;
  return { money: g.money, towers: g.towers.map(t => ({ type: t.type, level: t.level, x: Math.round(t.x), y: Math.round(t.y) })), selectedType: g.selectedType };
}));

// Select the new tower and inspect the panel.
await page.keyboard.press('Escape');
await page.mouse.click(spot.x, spot.y - 18);
await page.waitForTimeout(250);
log('inspector', await page.evaluate(() => ({
  selected: window.BTD.game.selectedTower?.type,
  panel: document.querySelector('#towerPanel').classList.contains('show'),
  name: document.querySelector('#towerName').textContent,
  level: document.querySelector('#towerLevel').textContent,
  upgrade: document.querySelector('#upgradeName').textContent,
  sell: document.querySelector('#sellValue').textContent,
  target: document.querySelector('#targetBtn b').textContent,
})));

// Upgrade twice and cycle target mode.
await page.locator('#upgradeBtn').click();
await page.waitForTimeout(200);
await page.locator('#upgradeBtn').click();
await page.waitForTimeout(200);
await page.locator('#targetBtn').click();
await page.waitForTimeout(150);
log('after upgrade', await page.evaluate(() => {
  const t = window.BTD.game.selectedTower;
  return { money: window.BTD.game.money, level: t.level, maxed: t.maxed, mode: t.modeInfo().label, desc: document.querySelector('#towerDesc').textContent, sell: document.querySelector('#sellValue').textContent };
}));

// Round 1 with 3x speed.
await page.locator('#startBtn').click();
await page.keyboard.press('f');
await page.keyboard.press('f');
await page.waitForTimeout(700);
log('round start', await page.evaluate(() => ({ round: window.BTD.game.round, active: window.BTD.game.roundActive, speed: window.BTD.game.speed, bloons: window.BTD.game.bloons.length, mid: document.querySelector('#roundSub').textContent })));
await page.screenshot({ path: '/tmp/opencode/round1.png' });

// Wait for round 1 to finish.
const start = Date.now();
let state;
do {
  await page.waitForTimeout(500);
  state = await page.evaluate(() => ({ round: window.BTD.game.round, active: window.BTD.game.roundActive, bloons: window.BTD.game.bloons.length, money: window.BTD.game.money, lives: window.BTD.game.lives, score: window.BTD.game.score, over: window.BTD.game.gameOver }));
} while (state.active && Date.now() - start < 30000);
log('round1 end', state);

// Auto-start should launch round 2 after a delay.
await page.locator('#autoBtn').click();
const autoStartAt = Date.now();
let autoState;
do {
  await page.waitForTimeout(500);
  autoState = await page.evaluate(() => ({ round: window.BTD.game.round, active: window.BTD.game.roundActive, auto: window.BTD.game.autoStart }));
} while (!autoState.active && Date.now() - autoStartAt < 12000);
log('auto start', autoState);

// Pause / help overlays.
await page.keyboard.press('p');
await page.waitForTimeout(250);
log('paused', await page.evaluate(() => ({ paused: window.BTD.game.paused, overlay: document.querySelector('#pauseOverlay').classList.contains('show') })));
