import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);

const result = await page.evaluate(() => {
  const g = window.BTD.game;
  const log = [];
  g.speed = 3;
  g.autoStart = true;
  g.lives = 99999;
  g.money = 100000;

  function place(type) {
    // Choose a spread-out valid spot near the track.
    const candidates = [];
    for (let y = 20; y < g.h - 20; y += 14) {
      for (let x = 20; x < g.w - 20; x += 14) {
        if (g.canPlace(type, x, y).ok) {
          const d = g.track.nearest(x, y).distance;
          if (d > g.pathWidth * 0.5 + 20 && d < 220) candidates.push({x, y, d});
        }
      }
    }
    candidates.sort(() => Math.random() - 0.5);
    for (const c of candidates) {
      if (g.towers.every(t => Math.hypot(t.x - c.x, t.y - c.y) > 90)) {
        return g.tryPlace(type, c.x, c.y);
      }
    }
    return false;
  }

  // Strong endgame defense.
  for (const type of ['super','super','super','ninja','bomb','sniper','ice','glue']) place(type);
  for (const t of g.towers) {
    while (!t.maxed && g.money > t.upgrade.cost) t.upgradeTower();
  }

  const start = performance.now();
  let lastRound = 0;
  let guard = 0;
  while (!g.gameOver && g.round < 30 && guard++ < 200000) {
    if (g.roundActive) {
      g.step(0.05);
    } else if (g.autoTimer > 0) {
      g.autoTimer = 0;
      g.startRound();
    } else {
      g.startRound();
    }
    if (g.round !== lastRound) {
      log.push({round: g.round, lives: g.lives, money: Math.round(g.money), towers: g.towers.length, active: g.roundActive});
      lastRound = g.round;
    }
  }
  // Let the final victory delay resolve.
  for (let i = 0; i < 100 && !g.gameOver; i++) g.step(0.05);
  return {
    over: g.gameOver, won: g.won, round: g.round, lives: g.lives, score: Math.round(g.score), pops: g.pops,
    towers: g.towers.map(t => ({type:t.type, level:t.level})),
    elapsedMs: Math.round(performance.now() - start),
    log,
    overlay: document.querySelector('#endOverlay').classList.contains('show'),
    title: document.querySelector('#endTitle').textContent,
  };
});
console.log(JSON.stringify(result, null, 2));
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/victory.png' });
console.log('errors', errors);
await browser.close();

