import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);

const results = await page.evaluate(() => {
  const g = window.BTD.game;

  function clearSpotNear(t, type, radius = 62, spacing = 48) {
    const p = g.track.pointAt(t);
    for (let r = radius; r <= radius + 90; r += 8) {
      for (let i = 0; i < 24; i++) {
        const a = (i / 24) * Math.PI * 2;
        const x = p.x + Math.cos(a) * r;
        const y = p.y + Math.sin(a) * r;
        if (!g.canPlace(type, x, y).ok) continue;
        if (g.towers.some(o => Math.hypot(o.x - x, o.y - y) < spacing)) continue;
        return { x, y };
      }
    }
    return null;
  }

  function buy(type, t, radius) {
    const spot = clearSpotNear(t, type, radius);
    if (!spot) return false;
    return g.tryPlace(type, spot.x, spot.y);
  }

  function upgradeAny(types) {
    const towers = g.towers
      .filter(t => !types || types.includes(t.type))
      .filter(t => !t.maxed)
      .sort((a, b) => a.level - b.level || a.def.cost - b.def.cost);
    for (const t of towers) {
      if (g.money >= t.upgrade.cost) {
        t.upgradeTower();
        return true;
      }
    }
    return false;
  }

  function run(plan) {
    g.restart();
    g.autoStart = false;
    g.speed = 3;
    g.money = 800;
    const log = [];
    let guard = 0;
    let bought = 0;

    while (!g.gameOver && guard++ < 500000) {
      if (g.roundActive || g.endDelay > 0) {
        g.step(0.05);
        continue;
      }
      if (g.round >= 30) { g.step(0.05); continue; }

      // Spend before each round.
      let purchased = true;
      let spendGuard = 0;
      while (purchased && spendGuard++ < 50) {
        purchased = false;
        // Buy the next planned tower if affordable.
        const next = plan.towers[bought];
        if (next && g.money >= BTD.TOWERS[next.type].cost) {
          if (buy(next.type, next.t, next.r)) {
            bought++;
            purchased = true;
            continue;
          }
        }
        // Upgrade existing defense.
        if (upgradeAny(plan.upgradeTypes)) purchased = true;
      }

      g.startRound();
      log.push({ round: g.round, money: Math.round(g.money), lives: g.lives, towers: g.towers.map(t => t.type[0] + (t.level + 1)).join(' ') });
    }
    for (let i = 0; i < 50 && !g.gameOver; i++) g.step(0.05);
    return {
      plan: plan.name,
      won: g.won, over: g.gameOver, round: g.round, lives: g.lives, money: Math.round(g.money), score: Math.round(g.score),
      towers: g.towers.map(t => ({ type: t.type, level: t.level })),
      log: log.slice(-5),
      purchased: bought,
    };
  }

  const plans = [
    {
      name: 'dart swarm',
      towers: [
        {type:'dart', t:0.16}, {type:'dart', t:0.7}, {type:'dart', t:0.4}, {type:'dart', t:0.85},
        {type:'dart', t:0.28}, {type:'dart', t:0.58}, {type:'dart', t:0.95}, {type:'super', t:0.5}
      ],
      upgradeTypes: ['dart', 'super']
    },
    {
      name: 'balanced arms',
      towers: [
        {type:'dart', t:0.16}, {type:'bomb', t:0.58}, {type:'sniper', t:0.32}, {type:'ninja', t:0.7},
        {type:'dart', t:0.4}, {type:'glue', t:0.75}, {type:'ice', t:0.55}, {type:'super', t:0.5}
      ],
      upgradeTypes: ['dart','bomb','sniper','ninja','super','glue','ice']
    },
    {
      name: 'quality first',
      towers: [
        {type:'dart', t:0.18}, {type:'dart', t:0.68}, {type:'ninja', t:0.5}, {type:'bomb', t:0.55},
        {type:'sniper', t:0.3}, {type:'super', t:0.5}
      ],
      upgradeTypes: ['dart','ninja','bomb','sniper','super']
    }
  ];
  return plans.map(run);
});
console.log(JSON.stringify(results, null, 2));
console.log('errors', errors);
await browser.close();

