import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);

const results = await page.evaluate(() => {
  const g = window.BTD.game;

  function coverageMap() {
    const samples = [];
    for (let i = 0; i < 120; i++) samples.push(g.track.pointAt(i / 119));
    return samples;
  }

  function bestSpot(type) {
    const def = BTD.TOWERS[type];
    const range = def.base.range * g.scale;
    const samples = coverageMap();
    const covered = new Array(samples.length).fill(false);
    for (const t of g.towers) {
      const r2 = t.range * t.range;
      samples.forEach((p, i) => {
        if ((p.x - t.x) ** 2 + (p.y - t.y) ** 2 <= r2) covered[i] = true;
      });
    }
    let best = null, bestScore = -1;
    for (let y = 30; y < g.h - 20; y += 12) {
      for (let x = 30; x < g.w - 20; x += 12) {
        if (!g.canPlace(type, x, y).ok) continue;
        const dTrack = g.track.nearest(x, y).distance;
        if (dTrack < g.pathWidth * 0.5 + 15 || dTrack > range * 0.95) continue;
        let score = 0;
        for (let i = 0; i < samples.length; i++) {
          if (covered[i]) continue;
          if ((samples[i].x - x) ** 2 + (samples[i].y - y) ** 2 <= range * range) score++;
        }
        // Favour symmetric central spots and some spacing.
        const spacing = g.towers.reduce((m, t) => Math.min(m, Math.hypot(t.x - x, t.y - y)), 9999);
        score += Math.min(spacing, 80) * 0.05;
        if (score > bestScore) { bestScore = score; best = { x, y, score }; }
      }
    }
    return best;
  }

  function buy(type) {
    const spot = bestSpot(type);
    if (!spot) return false;
    if (!g.tryPlace(type, spot.x, spot.y)) return false;
    return true;
  }

  function upgradeAny(types) {
    const towers = g.towers
      .filter(t => !types || types.includes(t.type))
      .filter(t => !t.maxed)
      .sort((a, b) => a.level - b.level || b.def.cost - a.def.cost);
    for (const t of towers) {
      if (g.money >= t.upgrade.cost) {
        t.upgradeTower();
        return true;
      }
    }
    return false;
  }

  function run(plan) {
    g.restart();
    g.autoStart = false;
    g.speed = 3;
    g.money = plan.startMoney ?? 800;
    const log = [];
    let guard = 0;
    let bought = 0;

    while (!g.gameOver && guard++ < 500000) {
      if (g.roundActive || g.endDelay > 0) { g.step(0.05); continue; }
      if (g.round >= 30) { g.step(0.05); continue; }

      let purchased = true, spendGuard = 0;
      while (purchased && spendGuard++ < 60) {
        purchased = false;
        const next = plan.towers[bought];
        if (next && g.money >= BTD.TOWERS[next.type].cost) {
          if (buy(next.type)) { bought++; purchased = true; continue; }
        }
        if (upgradeAny(plan.upgradeTypes)) purchased = true;
      }

      g.startRound();
      log.push({ round: g.round, money: Math.round(g.money), lives: g.lives, towers: g.towers.map(t => t.type[0] + (t.level + 1)).join(' ') });
    }
    for (let i = 0; i < 50 && !g.gameOver; i++) g.step(0.05);
    return {
      plan: plan.name, won: g.won, over: g.gameOver, round: g.round, lives: g.lives, money: Math.round(g.money),
      towers: g.towers.map(t => ({ type: t.type, level: t.level, x: Math.round(t.x), y: Math.round(t.y) })),
      log: log.slice(-8), purchased: bought,
    };
  }

  const plans = [
    {
      name: 'tack master',
      towers: [
        {type:'tack'},{type:'tack'},{type:'tack'},{type:'bomb'},{type:'tack'},{type:'glue'},{type:'tack'},{type:'super'}
      ],
      upgradeTypes: ['tack','bomb','glue','super']
    },
    {
      name: 'balanced coverage',
      towers: [
        {type:'dart'},{type:'bomb'},{type:'tack'},{type:'sniper'},{type:'ninja'},{type:'glue'},{type:'ice'},{type:'super'}
      ],
      upgradeTypes: ['dart','bomb','tack','sniper','ninja','glue','ice','super']
    },
    {
      name: 'ninja rush',
      towers: [
        {type:'ninja'},{type:'ninja'},{type:'ninja'},{type:'bomb'},{type:'ninja'},{type:'sniper'},{type:'super'}
      ],
      upgradeTypes: ['ninja','bomb','sniper','super']
    },
    {
      name: 'quality',
      towers: [
        {type:'dart'},{type:'bomb'},{type:'ninja'},{type:'sniper'},{type:'super'},{type:'super'}
      ],
      upgradeTypes: ['dart','bomb','ninja','sniper','super']
    }
  ];
  return plans.map(run);
});
console.log(JSON.stringify(results, null, 2));
console.log('errors', errors);
await browser.close();

