import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);

const results = await page.evaluate(() => {
  const g = window.BTD.game;
  function bestSpot(type) {
    const def = BTD.TOWERS[type], range = def.base.range * g.scale;
    const samples = []; for (let i = 0; i < 120; i++) samples.push(g.track.pointAt(i / 119));
    const covered = new Array(samples.length).fill(false);
    for (const t of g.towers) {
      const r2 = t.range * t.range;
      samples.forEach((p, i) => { if ((p.x - t.x) ** 2 + (p.y - t.y) ** 2 <= r2) covered[i] = true; });
    }
    let best = null, bestScore = -1;
    for (let y = 30; y < g.h - 20; y += 10) for (let x = 30; x < g.w - 20; x += 10) {
      if (!g.canPlace(type, x, y).ok) continue;
      const dt = g.track.nearest(x, y).distance;
      if (dt < g.pathWidth * 0.5 + 15 || dt > range * 0.9) continue;
      let score = 0;
      for (let i = 0; i < samples.length; i++) if (!covered[i] && (samples[i].x - x) ** 2 + (samples[i].y - y) ** 2 <= range * range) score++;
      const spacing = g.towers.reduce((m, t) => Math.min(m, Math.hypot(t.x - x, t.y - y)), 9999);
      score += Math.min(spacing, 90) * 0.08;
      if (score > bestScore) { bestScore = score; best = { x, y }; }
    }
    return best;
  }
  function buy(type) { const s = bestSpot(type); return s ? g.tryPlace(type, s.x, s.y) : false; }
  function upgradeAll(types) {
    const t = g.towers.filter(t => !types || types.includes(t.type)).filter(t => !t.maxed)
      .sort((a,b) => a.level - b.level || b.def.cost - a.def.cost)[0];
    if (t && g.money >= t.upgrade.cost) return t.upgradeTower();
    return false;
  }
  function run(name, startMoney, plan) {
    g.restart(); g.speed = 3; g.money = startMoney;
    let bought = 0, guard = 0, log = [];
    while (!g.gameOver && guard++ < 600000) {
      if (g.roundActive || g.endDelay > 0) { g.step(0.05); continue; }
      if (g.round >= 30) { g.step(0.05); continue; }
      // Buy every planned cheap tower before spending on upgrades.
      for (const type of plan) {
        if (g.money >= BTD.TOWERS[type].cost && buy(type)) {
          // if placement failed, avoid infinite loop by moving on
        }
      }
      let guard2 = 0;
      while (g.money >= 140 && guard2++ < 50 && upgradeAll(null));
      g.startRound();
      log.push({round:g.round,lives:g.lives,money:Math.round(g.money),towers:g.towers.map(t=>t.type[0]+(t.level+1)).join(' ')});
    }
    for (let i=0;i<60&&!g.gameOver;i++) g.step(0.05);
    return {name, startMoney, won:g.won, round:g.round, lives:g.lives, money:Math.round(g.money), towers:g.towers.map(t=>({type:t.type,level:t.level,x:Math.round(t.x),y:Math.round(t.y)})), log:log.slice(-4)};
  }
  const plans = {
    cheap: ['dart','dart','dart','dart','tack','tack','bomb','sniper','ninja','super'],
    mix: ['dart','tack','boomerang','bomb','sniper','ninja','ice','glue','super'],
  };
  const out = [];
  for (const start of [800, 1000, 1200, 1500]) {
    for (const [name, plan] of Object.entries(plans)) out.push(run(name, start, plan));
  }
  return out;
});
console.log(JSON.stringify(results, null, 2));
console.log('errors', errors);
await browser.close();

