  const g = window.BTD.game;
  const anchors = [{x:0.445,y:0.40},{x:0.74,y:0.42},{x:0.25,y:0.49},{x:0.72,y:0.72}];
  function placeNear(type, ax, ay, minGap = 30) {
    const cx = ax * g.w, cy = ay * g.h;
    for (let r = 34; r <= 150; r += 8) for (let i = 0; i < 30; i++) {
      const a = i / 30 * Math.PI * 2 + r;
      const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r;
      if (!g.canPlace(type, x, y).ok) continue;
      if (g.towers.some(t => Math.hypot(t.x - x, t.y - y) < minGap)) continue;
      return g.tryPlace(type, x, y);
    }
    return false;
  }
  function upgradesAll(types, maxLevel = 3) {
    let bought = false;
    for (const t of g.towers.slice().sort((a,b) => a.level - b.level || a.def.cost - b.def.cost)) {
      if (types && !types.includes(t.type)) continue;
      while (!t.maxed && t.level < maxLevel && g.money >= t.upgrade.cost) {
        t.upgradeTower(); bought = true;
      }
    }
    return bought;
  }
  function run(name, plan, startMoney) {
    g.restart(); g.speed = 3; g.money = startMoney;
    let bought = 0, guard = 0, log = [];
    while (!g.gameOver && guard++ < 600000) {
      if (g.roundActive || g.endDelay > 0) { g.step(0.05); continue; }
      if (g.round >= 30) { g.step(0.05); continue; }
      // Buy first 6 towers as soon as affordable.
      while (bought < plan.length) {
        const it = plan[bought];
        if (g.money < BTD.TOWERS[it.type].cost) break;
        if (!placeNear(it.type, it.a[0], it.a[1])) { bought++; continue; }
        bought++;
      }
      // Upgrade existing defense.
      for (let i=0;i<30;i++) if (!upgradesAll(null, 3)) break;
      g.startRound();
      log.push({round:g.round,lives:g.lives,money:Math.round(g.money),towers:g.towers.map(t=>t.type[0]+(t.level+1)).join(' ')});
    }
    for (let i=0;i<60&&!g.gameOver;i++) g.step(0.05);
    return {name, startMoney, won:g.won, round:g.round, lives:g.lives, money:Math.round(g.money),
      towers:g.towers.map(t=>({type:t.type,level:t.level,x:Math.round(t.x),y:Math.round(t.y)})), log:log.slice(-6)};
  }
  const anchor = (i) => anchors[i % anchors.length];
  const plans = {
    dartchoke: [
      {type:'dart',a:[0.445,0.4]},{type:'dart',a:[0.445,0.4]},{type:'dart',a:[0.445,0.4]},
      {type:'dart',a:[0.74,0.42]},{type:'dart',a:[0.74,0.42]},{type:'dart',a:[0.25,0.49]},
      {type:'bomb',a:[0.445,0.4]},{type:'sniper',a:[0.25,0.49]},{type:'ninja',a:[0.74,0.42]},{type:'super',a:[0.445,0.4]}
    ],
    mixchoke: [
      {type:'dart',a:[0.445,0.4]},{type:'tack',a:[0.445,0.4]},{type:'ninja',a:[0.74,0.42]},
      {type:'bomb',a:[0.445,0.4]},{type:'dart',a:[0.25,0.49]},{type:'tack',a:[0.74,0.42]},
      {type:'sniper',a:[0.25,0.49]},{type:'glue',a:[0.445,0.4]},{type:'super',a:[0.445,0.4]}
    ],
    threechoke: [
      {type:'tack',a:[0.445,0.4]},{type:'dart',a:[0.445,0.4]},{type:'bomb',a:[0.74,0.42]},
      {type:'ninja',a:[0.74,0.42]},{type:'tack',a:[0.25,0.49]},{type:'dart',a:[0.25,0.49]},
      {type:'sniper',a:[0.72,0.72]},{type:'ice',a:[0.445,0.4]},{type:'super',a:[0.445,0.4]}
    ]
  };
  const out = [];
  for (const start of [1100, 1500]) for (const [name, plan] of Object.entries(plans)) out.push(run(name, plan, start));
  return out;
});
