import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
await page.goto('http://localhost:3000/',{waitUntil:'networkidle'});
await page.waitForTimeout(700);
const out = await page.evaluate(() => {
  const g=window.BTD.game;
  function test(type,n,round,mode) {
    g.restart();g.speed=3;g.money=999999;g.lives=150;g.round=round-1;
    const anchors=[[0.445,0.4],[0.74,0.42],[0.25,0.49],[0.72,0.72]];
    for(let i=0;i<n;i++){
      const a=mode==='choke'?anchors[0]:anchors[i%anchors.length];
      let placed=false;
      for(let r=0;r<220&&!placed;r+=8)for(let k=0;k<24&&!placed;k++){
        const ang=k/24*Math.PI*2+r, x=a[0]*g.w+Math.cos(ang)*r, y=a[1]*g.h+Math.sin(ang)*r;
        if(!g.canPlace(type,x,y).ok)continue;
        if(g.towers.some(t=>Math.hypot(t.x-x,t.y-y)<22))continue;
        placed=g.tryPlace(type,x,y);
      }
    }
    for(const t of g.towers)while(!t.maxed)t.upgradeTower();
    g.money=0; const old=g.onLeak.bind(g); let leaks=0; g.onLeak=(b,p)=>{leaks++;old(b,p);};
    g.startRound(); let steps=0; while(g.roundActive&&steps++<4000)g.step(0.05);
    g.onLeak=old;
    return {type,n,round,mode,lives:g.lives,leaks,pops:g.pops};
  }
  const out=[];
  for(const type of ['dart','tack','bomb','ninja','boomerang','sniper','super'])for(const mode of ['choke','spread'])for(const round of [13,14,15]){
    for(const n of [2,3,4,5,6,8,10]) out.push(test(type,n,round,mode));
  }
  return out;
});
const groups={};
for(const r of out){const k=r.type+' '+r.mode;(groups[k]??=[]).push(r);}
for(const [k,list] of Object.entries(groups)){
  console.log('--- '+k);
  for(const r of list) console.log(`  r${r.round} n${r.n} lives ${String(r.lives).padStart(3)} leaks ${String(r.leaks).padStart(2)}`);
}
await browser.close();

import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
const errors=[]; page.on('pageerror',e=>errors.push(String(e)));
await page.goto('http://localhost:3000/',{waitUntil:'networkidle'});
await page.waitForTimeout(700);
const results = await page.evaluate(() => {
  const g=window.BTD.game;
  function placeNear(type,ax,ay,minGap=24){const cx=ax*g.w,cy=ay*g.h;
    for(let r=24;r<=170;r+=6)for(let i=0;i<36;i++){const a=i/36*Math.PI*2+r,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;
      if(!g.canPlace(type,x,y).ok)continue;if(g.towers.some(t=>Math.hypot(t.x-x,t.y-y)<minGap))continue;return g.tryPlace(type,x,y);}
    return false;}
  function buySpread(type){const def=BTD.TOWERS[type],range=def.base.range*g.scale;
    const samples=[];for(let i=0;i<120;i++)samples.push(g.track.pointAt(i/119));
    const covered=new Array(samples.length).fill(false);
    for(const t of g.towers){const r2=t.range*t.range;samples.forEach((p,i)=>{if((p.x-t.x)**2+(p.y-t.y)**2<=r2)covered[i]=true;});}
    let best=null,bs=-1;
    for(let y=30;y<g.h-20;y+=10)for(let x=30;x<g.w-20;x+=10){
      if(!g.canPlace(type,x,y).ok)continue;const dt=g.track.nearest(x,y).distance;
      if(dt<g.pathWidth*.5+15||dt>range*.9)continue;
      let s=0;for(let i=0;i<samples.length;i++)if(!covered[i]&&(samples[i].x-x)**2+(samples[i].y-y)**2<=range*range)s++;
      if(s>bs){bs=s;best={x,y};}}
    return best?g.tryPlace(type,best.x,best.y):false;}
  function run(name,leadType,plan,mode){g.restart();g.speed=3;g.money=1100;let idx=0,guard=0,log=[];
    const anchors=[[0.445,0.4],[0.74,0.42],[0.25,0.49],[0.72,0.72],[0.445,0.4],[0.74,0.42]];
    while(!g.gameOver&&guard++<900000){
      if(g.roundActive||g.endDelay>0){g.step(0.05);continue;}
      if(g.round>=30){g.step(0.05);continue;}
      let steps=0;
      while(steps++<80){
        let did=false;
        // Keep buying planned towers.
        if(idx<plan.length){const type=plan[idx];if(g.money>=BTD.TOWERS[type].cost){const a=anchors[idx%anchors.length];const ok=mode==='spread'?buySpread(type):placeNear(type,a[0],a[1],22);if(ok){idx++;did=true;}else idx++;}}
        // Focus the lead tower to max first, then everything else.
        const lead=g.towers.find(t=>t.type===leadType);
        if(lead&&!lead.maxed&&g.money>=lead.upgrade.cost){lead.upgradeTower();did=true;}
        const cands=g.towers.filter(t=>!t.maxed&&g.money>=t.upgrade.cost).sort((a,b)=>b.level-a.level||a.def.cost-b.def.cost);
        if(cands.length){cands[0].upgradeTower();did=true;}
        if(!did)break;
      }
      g.startRound();
      log.push({round:g.round,lives:g.lives,money:Math.round(g.money),towers:g.towers.map(t=>t.type[0]+(t.level+1)).join(' ')});
    }
    for(let i=0;i<60&&!g.gameOver;i++)g.step(0.05);
    return {name,mode,won:g.won,round:g.round,lives:g.lives,money:Math.round(g.money),towers:g.towers.map(t=>({type:t.type,level:t.level})),log:log.slice(-5)};
  }
  const plans={
    tackRush:['tack','tack','tack','tack','bomb','sniper','tack','tack','super','dart'],
    ninjaRush:['ninja','ninja','ninja','bomb','tack','sniper','ninja','tack','super','dart'],
    boomerRush:['boomerang','boomerang','bomb','tack','sniper','boomerang','tack','super','dart'],
  };
  const out=[];
  for(const [name,plan] of Object.entries(plans))for(const mode of ['choke','spread']){
    const lead=plan[0];out.push(run(name,lead,plan,mode));
  }
  return out;
});
for(const r of results) console.log(`${r.name.padEnd(11)} ${r.mode.padEnd(6)} round ${String(r.round).padStart(2)} lives ${String(r.lives).padStart(3)} money ${String(r.money).padStart(5)} won=${r.won} towers ${r.towers.length}`);
console.log('errors',errors);
await browser.close();

