    ['saveNinja', ['ninja','tack','bomb','sniper','tack','ninja'], { reserve: 400 }],
    ['slowBuild', ['dart','tack','ninja','bomb','sniper','tack','ninja'], { reserve: 250, maxTowers: 7 }],
  ];
  for (const [name, plan, opts] of strategies) out.push(run(name, plan, opts));
