await page.waitForTimeout(700);
const results = await page.evaluate(() => {
  const g = window.BTD.game;
  function bestSpot(type) {
    const def = BTD.TOWERS[type], range = def.base.range * g.scale;
    const samples = []; for (let i = 0; i < 150; i++) samples.push(g.track.pointAt(i / 149));
    const covered = new Array(samples.length).fill(false);
    for (const t of g.towers) {
      const r2 = t.range * t.range;
      samples.forEach((p, i) => { if ((p.x - t.x) ** 2 + (p.y - t.y) ** 2 <= r2) covered[i] = true; });
    }
    let best = null, bestScore = -1;
    for (let y = 30; y < g.h - 20; y += 8) for (let x = 30; x < g.w - 20; x += 8) {
      if (!g.canPlace(type, x, y).ok) continue;
      const dt = g.track.nearest(x, y).distance;
      if (dt < g.pathWidth * 0.5 + 15 || dt > range * 0.9) continue;
      let score = 0;
      for (let i = 0; i < samples.length; i++) if (!covered[i] && (samples[i].x - x) ** 2 + (samples[i].y - y) ** 2 <= range * range) score++;
      const spacing = g.towers.reduce((m, t) => Math.min(m, Math.hypot(t.x - x, t.y - y)), 9999);
      score += Math.min(spacing, 100) * 0.06;
      if (score > bestScore) { bestScore = score; best = { x, y }; }
    }
    return best;
  }
  function buy(type) { const s = bestSpot(type); return s ? g.tryPlace(type, s.x, s.y) : false; }
  function run(name, leadType, extras) {
    g.restart(); g.speed = 3;
    let guard = 0, log = [], idx = 0;
    while (!g.gameOver && guard++ < 900000) {
      if (g.roundActive || g.endDelay > 0) { g.step(0.05); continue; }
      if (g.round >= 30) { g.step(0.05); continue; }
      let act = 0;
      while (act++ < 80) {
        let did = false;
        // Hard rush the lead tower to max before anything else.
        let lead = g.towers.find(t => t.type === leadType);
        if (!lead && g.money >= BTD.TOWERS[leadType].cost) {
          if (buy(leadType)) did = true;
        } else if (lead && !lead.maxed && g.money >= lead.upgrade.cost) {
          lead.upgradeTower(); did = true;
        } else if (lead && lead.maxed) {
          // Then spend on extras and cheap upgrades.
          const t = g.towers.filter(t => !t.maxed && g.money >= t.upgrade.cost).sort((a, b) => a.level - b.level)[0];
          if (t) { t.upgradeTower(); did = true; }
          else if (idx < extras.length && g.money >= BTD.TOWERS[extras[idx]].cost) {
            if (buy(extras[idx])) { idx++; did = true; } else idx++;
          }
        }
        if (!did) break;
      }
      g.startRound();
      log.push({ round: g.round, lives: g.lives, money: Math.round(g.money), towers: g.towers.map(t => t.type[0] + (t.level + 1)).join(' ') });
    }
    for (let i = 0; i < 60 && !g.gameOver; i++) g.step(0.05);
    return { name, won: g.won, round: g.round, lives: g.lives, money: Math.round(g.money), towers: g.towers.map(t => t.type + (t.level + 1)), log: log.slice(-4), last: log };
  }
  const out = [
    run('ninjaMax', 'ninja', ['tack', 'bomb', 'sniper', 'tack', 'ninja']),
    run('tackMax', 'tack', ['ninja', 'bomb', 'sniper', 'tack']),
    run('boomerMax', 'boomerang', ['ninja', 'tack', 'bomb', 'sniper']),
  ];
  return out;
});
